css:
@property --apb-envelope-sweep { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes apb-envelope-sweep { to { --apb-envelope-sweep: 360deg; } }
@keyframes apb-envelope-pulse { 0% { transform: scale(1); } 35% { transform: scale(1.14); } 100% { transform: scale(1); } }
@keyframes apb-envelope-shadow { from { box-shadow: 0 0 0 0 transparent; } to { box-shadow: 0 10px 18px -14px var(--apb-envelope-shade); } }
@keyframes apb-envelope-rise { from { opacity: 0; transform: translateY(8px); } }

.apb-envelope {
  --apb-envelope-bg: oklch(0.975 0.012 85);
  --apb-envelope-ink: oklch(0.27 0.025 60);
  --apb-envelope-accent: oklch(0.49 0.1 155);
  --apb-envelope-warn: oklch(0.6 0.15 38);
  --apb-envelope-gold: oklch(0.8 0.13 80);
  --apb-envelope-g1: oklch(0.56 0.07 245);
  --apb-envelope-g2: var(--apb-envelope-accent);
  --apb-envelope-g3: oklch(0.74 0.12 82);
  --apb-envelope-g4: oklch(0.62 0.13 30);
  --apb-envelope-paper: color-mix(in oklch, white 70%, var(--apb-envelope-bg));
  --apb-envelope-sunk: color-mix(in oklch, var(--apb-envelope-ink) 5%, var(--apb-envelope-bg));
  --apb-envelope-line: color-mix(in oklch, var(--apb-envelope-ink) 12%, transparent);
  --apb-envelope-line2: color-mix(in oklch, var(--apb-envelope-ink) 22%, transparent);
  --apb-envelope-mute: color-mix(in oklch, var(--apb-envelope-ink) 58%, var(--apb-envelope-bg));
  --apb-envelope-tint: color-mix(in oklch, var(--apb-envelope-accent) 12%, var(--apb-envelope-bg));
  --apb-envelope-shade: color-mix(in oklch, var(--apb-envelope-ink) 45%, transparent);
  --apb-envelope-ease: cubic-bezier(.2, .8, .2, 1);
  --apb-envelope-spring: linear(0, .09 4%, .33 9%, .64 15%, .88 21%, 1.02 27%, 1.07 32%, 1.06 38%, 1.02 46%, .995 58%, 1);
  --apb-envelope-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; box-sizing: border-box; width: 100%; height: var(--apb-envelope-h, 680px);
  container-type: inline-size; container-name: apb-envelope;
  display: block; overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apb-envelope-line);
  background: var(--apb-envelope-bg); color: var(--apb-envelope-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--apb-envelope-accent);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & svg { display: block; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apb-envelope-accent); outline-offset: 2px; border-radius: 6px; }
  & kbd { font: 600 10.5px/1 var(--apb-envelope-mono); padding: 3px 5px; min-width: 18px; text-align: center; border-radius: 5px; border: 1px solid var(--apb-envelope-line2); border-bottom-width: 2px; background: var(--apb-envelope-paper); color: var(--apb-envelope-mute); }
  & .is-num, & [data-num] { font-variant-numeric: tabular-nums; }

  & .apb-envelope-app { display: grid; height: 100%; grid-template-columns: 218px minmax(0, 1fr) 316px; grid-template-rows: minmax(0, 1fr); grid-template-areas: "side main detail"; }

  /* ── side: accounts and the shortcut legend ── */
  & .apb-envelope-side { grid-area: side; display: flex; flex-direction: column; gap: 10px; padding: 18px 16px; border-right: 1px solid var(--apb-envelope-line); background: var(--apb-envelope-sunk); overflow: auto; overscroll-behavior: contain; }
  & .apb-envelope-brand { display: grid; grid-template-columns: auto 1fr; column-gap: 9px; align-items: center; margin-bottom: 8px;
    & svg { grid-row: span 2; width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--apb-envelope-accent); color: var(--apb-envelope-bg); stroke-width: 2; }
    & b { font-size: 16px; font-weight: 800; letter-spacing: -.01em; line-height: 1.1; }
    & span { font-size: 12px; color: var(--apb-envelope-mute); }
  }
  & .apb-envelope-side h3 { margin: 10px 0 0; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apb-envelope-mute); }
  & .apb-envelope-accts { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px;
    & li { display: flex; justify-content: space-between; gap: 8px; padding: 6px 0; font-size: 13px; }
    & b { font-weight: 600; font-variant-numeric: tabular-nums; }
    & .is-total { border-top: 1px dashed var(--apb-envelope-line2); margin-top: 4px; padding-top: 9px; font-weight: 700; }
  }
  & .apb-envelope-hint { margin: 0; font-size: 12px; line-height: 1.5; color: var(--apb-envelope-mute); text-wrap: pretty; & em { font-style: normal; color: var(--apb-envelope-accent); font-weight: 600; } }
  & .apb-envelope-keys { margin: 0; display: grid; gap: 7px;
    & div { display: grid; grid-template-columns: 64px 1fr; align-items: center; gap: 8px; }
    & dt { display: flex; gap: 3px; }
    & dd { margin: 0; font-size: 12px; color: var(--apb-envelope-mute); }
  }

  /* ── main column ── */
  & .apb-envelope-main { grid-area: main; display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; }
  & .apb-envelope-head { display: grid; grid-template-columns: 1fr auto; grid-template-areas: "month tools" "rta rta" "filters filters"; gap: 12px 10px; padding: 16px 20px 12px; }
  & .apb-envelope-month { grid-area: month; display: flex; align-items: center; gap: 4px; min-width: 0;
    & h2 { margin: 0 6px; font-size: clamp(17px, 1.2cqi + 6px, 21px); font-weight: 750; letter-spacing: -.015em; text-wrap: balance; white-space: nowrap; }
  }
  & .apb-envelope-state { margin-left: 6px; padding: 3px 8px; border-radius: 99px; font-size: 11px; font-weight: 650; letter-spacing: .02em; background: var(--apb-envelope-sunk); color: var(--apb-envelope-mute); white-space: nowrap; }
  & .apb-envelope-tools { grid-area: tools; display: flex; gap: 6px; }
  & .apb-envelope-ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--apb-envelope-ink); transition: background-color .18s, transform .18s var(--apb-envelope-ease);
    &:hover:not(:disabled) { background: var(--apb-envelope-sunk); }
    &:active:not(:disabled) { transform: scale(.94); }
  }

  /* Ready to assign: the figure and how this month's income is spread across groups */
  & .apb-envelope-rta { grid-area: rta; position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "fig act" "bar bar"; align-items: center; gap: 12px 18px; padding: 12px 14px 12px 16px; border-radius: 14px; background: var(--apb-envelope-paper); border: 1px solid var(--apb-envelope-line); isolation: isolate;
    &::before { content: ""; position: absolute; inset: -1px; z-index: -1; border-radius: inherit; padding: 1.5px; background: conic-gradient(from var(--apb-envelope-sweep), transparent 0 70%, var(--apb-envelope-accent) 85%, transparent 100%); -webkit-mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); opacity: 0; transition: opacity .4s; }
    &[data-tone="zero"]::before { opacity: 1; animation: apb-envelope-sweep 2.4s linear infinite; }
    &[data-tone="neg"] { background: color-mix(in oklch, var(--apb-envelope-warn) 9%, var(--apb-envelope-paper)); border-color: color-mix(in oklch, var(--apb-envelope-warn) 35%, transparent); }
    &.is-target { outline: 2px dashed var(--apb-envelope-accent); outline-offset: 2px; }
  }
  & .apb-envelope-fig { grid-area: fig; display: grid; min-width: 0;
    & p { margin: 3px 0 0; font-size: 11.5px; color: var(--apb-envelope-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apb-envelope-mute); }
    & b { font-size: clamp(24px, 2.2cqi + 6px, 32px); font-weight: 800; letter-spacing: -.03em; line-height: 1.05; font-variant-numeric: tabular-nums; color: var(--apb-envelope-accent); transition: color .3s; }
  }
  & .apb-envelope-rta[data-tone="neg"] .apb-envelope-fig b { color: var(--apb-envelope-warn); }
  & .apb-envelope-rta[data-tone="zero"] .apb-envelope-fig b { color: var(--apb-envelope-ink); }
  & .apb-envelope-spread { grid-area: bar; display: grid; gap: 8px; min-width: 0; }
  & .apb-envelope-bar { display: flex; height: 10px; border-radius: 99px; overflow: hidden; background: var(--apb-envelope-sunk); gap: 2px;
    & i { display: block; flex: var(--w) 0 0; min-width: 0; background: var(--c); transition: flex-grow .7s var(--apb-envelope-spring); }
    & i:last-child { background: repeating-linear-gradient(-45deg, var(--apb-envelope-tint) 0 4px, transparent 4px 8px); }
  }
  & .apb-envelope-legend { display: flex; flex-wrap: wrap; gap: 3px 16px; font-size: 11px; color: var(--apb-envelope-mute); font-variant-numeric: tabular-nums;
    & span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
    & b { font-weight: 650; color: var(--apb-envelope-ink); }
    & span::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: var(--c); }
  }
  & .apb-envelope-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 34px; padding: 0 13px; border-radius: 10px; font-size: 13px; font-weight: 650; white-space: nowrap; background: var(--apb-envelope-ink); color: var(--apb-envelope-bg); transition: transform .2s var(--apb-envelope-ease), background-color .2s;
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--apb-envelope-ink) 86%, var(--apb-envelope-accent)); }
    &:active:not(:disabled) { transform: translateY(1px) scale(.98); }
    & svg { width: 16px; height: 16px; }
    &.is-soft { background: var(--apb-envelope-sunk); color: var(--apb-envelope-ink); &:hover:not(:disabled) { background: color-mix(in oklch, var(--apb-envelope-ink) 10%, var(--apb-envelope-bg)); } }
    &.is-accent { background: var(--apb-envelope-accent); color: var(--apb-envelope-bg); &:hover:not(:disabled) { background: color-mix(in oklch, var(--apb-envelope-accent) 85%, black); } }
    & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, currentColor 35%, transparent); opacity: .85; }
  }
  & .apb-envelope-rta .apb-envelope-btn { grid-area: act; }

  & .apb-envelope-filters { grid-area: filters; display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
  & .apb-envelope-chips { display: flex; gap: 4px; padding: 3px; border-radius: 11px; background: var(--apb-envelope-sunk); overflow-x: auto; scrollbar-width: none;
    & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--apb-envelope-mute); white-space: nowrap; transition: background-color .2s, color .2s, box-shadow .2s; }
    & button:hover { color: var(--apb-envelope-ink); }
    & button[aria-selected="true"] { background: var(--apb-envelope-paper); color: var(--apb-envelope-ink); box-shadow: 0 1px 2px var(--apb-envelope-line2), 0 0 0 1px var(--apb-envelope-line); }
    & i { font-style: normal; font-size: 11px; min-width: 18px; padding: 1px 5px; border-radius: 99px; background: var(--apb-envelope-line); font-variant-numeric: tabular-nums; }
    & i:empty { display: none; }
  }
  & .apb-envelope-search { display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 8px 0 10px; border-radius: 10px; border: 1px solid var(--apb-envelope-line); background: var(--apb-envelope-paper); color: var(--apb-envelope-mute); width: min(220px, 100%); transition: border-color .2s, box-shadow .2s;
    &:focus-within { border-color: var(--apb-envelope-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apb-envelope-accent) 18%, transparent); }
    & svg { width: 16px; height: 16px; }
    & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 13px; color: var(--apb-envelope-ink); }
    & input::-webkit-search-cancel-button { display: none; }
  }

  /* ── envelope grid ── */
  & .apb-envelope-scroller { overflow: auto; overscroll-behavior: contain; padding: 0 12px 24px 20px; scrollbar-width: thin; scrollbar-color: var(--apb-envelope-line2) transparent; }
  & .apb-envelope-cols, & .apb-envelope-row { display: grid; grid-template-columns: minmax(0, 1fr) 112px 96px 112px; align-items: center; column-gap: 12px; }
  & .apb-envelope-cols { position: sticky; top: 0; z-index: 2; padding: 8px 10px; background: var(--apb-envelope-bg); font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apb-envelope-mute); border-bottom: 1px solid var(--apb-envelope-line);
    & span:not(:first-child) { text-align: right; }
  }
  @supports (animation-timeline: scroll()) {
    & .apb-envelope-cols { animation: apb-envelope-shadow linear both; animation-timeline: scroll(nearest block); animation-range: 0 40px; }
  }
  & .apb-envelope-group { display: flex; align-items: center; gap: 8px; width: 100%; padding: 14px 10px 6px; text-align: left; font-size: 11px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--apb-envelope-mute);
    & svg { width: 14px; height: 14px; transition: transform .3s var(--apb-envelope-ease); }
    &[aria-expanded="false"] svg { transform: rotate(-90deg); }
    & .apb-envelope-gsum { margin-left: auto; letter-spacing: 0; text-transform: none; font-weight: 600; font-variant-numeric: tabular-nums; }
    &:hover { color: var(--apb-envelope-ink); }
    &::after { content: ""; flex: 0 0 8px; height: 8px; border-radius: 2px; background: var(--c); order: -1; }
  }
  & .apb-envelope-row { position: relative; padding: 7px 10px; border-radius: 11px; transition: background-color .18s;
    animation: apb-envelope-rise .42s var(--apb-envelope-ease) both; animation-delay: calc(var(--i, 0) * 22ms);
    &:hover { background: var(--apb-envelope-sunk); }
    &[aria-selected="true"] { background: var(--apb-envelope-tint); box-shadow: inset 3px 0 0 var(--apb-envelope-accent); }
    &.is-over { background: color-mix(in oklch, var(--apb-envelope-accent) 20%, var(--apb-envelope-bg)); box-shadow: inset 0 0 0 2px var(--apb-envelope-accent); }
    &.is-source { opacity: .55; }
  }
  & .apb-envelope-name { display: grid; gap: 5px; min-width: 0; text-align: left; padding: 3px 2px; border-radius: 6px;
    & b { font-weight: 620; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { font-size: 11.5px; color: var(--apb-envelope-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small.is-under { color: color-mix(in oklch, var(--apb-envelope-gold) 55%, var(--apb-envelope-ink)); }
    & small.is-over { color: var(--apb-envelope-warn); }
  }
  & .apb-envelope-fill { position: relative; height: 4px; border-radius: 99px; background: var(--apb-envelope-line); overflow: hidden;
    & i { position: absolute; inset: 0; border-radius: inherit; background: var(--c, var(--apb-envelope-accent)); transform-origin: left; transform: scaleX(var(--p, 0)); transition: transform .8s var(--apb-envelope-spring); }
  }
  & .apb-envelope-amt { width: 100%; height: 32px; padding: 0 8px; border-radius: 8px; border: 1px solid transparent; background: transparent; text-align: right; font-variant-numeric: tabular-nums; font-size: 13.5px; transition: border-color .15s, background-color .15s;
    &:hover:not(:disabled) { border-color: var(--apb-envelope-line2); background: var(--apb-envelope-paper); }
    &:focus { outline: 0; border-color: var(--apb-envelope-accent); background: var(--apb-envelope-paper); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apb-envelope-accent) 18%, transparent); }
    &:disabled { color: var(--apb-envelope-mute); }
  }
  & .apb-envelope-act { text-align: right; font-size: 13.5px; color: var(--apb-envelope-mute); font-variant-numeric: tabular-nums; }
  & .apb-envelope-avail { justify-self: end; display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 99px; font-weight: 700; font-size: 13.5px; font-variant-numeric: tabular-nums; cursor: grab; touch-action: none; user-select: none;
    background: color-mix(in oklch, var(--apb-envelope-accent) 16%, var(--apb-envelope-bg)); color: color-mix(in oklch, var(--apb-envelope-accent) 80%, black);
    transition: transform .25s var(--apb-envelope-ease), box-shadow .2s, background-color .3s, color .3s;
    &:hover:not(:disabled) { transform: translateY(-1px); box-shadow: 0 4px 10px -6px var(--apb-envelope-shade); }
    &[data-tone="zero"] { background: var(--apb-envelope-sunk); color: var(--apb-envelope-mute); }
    &[data-tone="under"] { background: color-mix(in oklch, var(--apb-envelope-gold) 30%, var(--apb-envelope-bg)); color: color-mix(in oklch, var(--apb-envelope-gold) 40%, black); }
    &[data-tone="over"] { background: var(--apb-envelope-warn); color: var(--apb-envelope-bg); }
    &.is-pulse { animation: apb-envelope-pulse .5s var(--apb-envelope-ease); }
    &:disabled { cursor: not-allowed; opacity: 1; }
  }
  & .apb-envelope-empty { padding: 48px 12px; text-align: center; color: var(--apb-envelope-mute); text-wrap: balance;
    & b { display: block; color: var(--apb-envelope-ink); font-size: 15px; margin-bottom: 4px; }
    & .apb-envelope-btn { margin-top: 14px; }
  }

  /* ── detail ── */
  & .apb-envelope-detail { grid-area: detail; display: flex; flex-direction: column; min-height: 0; scroll-padding-bottom: 76px; border-left: 1px solid var(--apb-envelope-line); background: var(--apb-envelope-paper); overflow: auto; overscroll-behavior: contain; }
  & .apb-envelope-dhead { padding: 18px 18px 14px; border-bottom: 1px solid var(--apb-envelope-line);
    & .apb-envelope-back { display: none; width: fit-content; align-items: center; gap: 4px; margin: -4px 0 10px -6px; padding: 4px 8px 4px 4px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--apb-envelope-accent); }
    & small { font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apb-envelope-mute); }
    & h3 { margin: 2px 0 12px; font-size: 20px; font-weight: 760; letter-spacing: -.02em; text-wrap: balance; }
  }
  & .apb-envelope-big { display: flex; align-items: baseline; gap: 10px;
    & b { font-size: clamp(28px, 2.6cqi, 36px); font-weight: 800; letter-spacing: -.035em; font-variant-numeric: tabular-nums; line-height: 1; }
    & span { font-size: 12.5px; color: var(--apb-envelope-mute); }
    &[data-tone="over"] b { color: var(--apb-envelope-warn); }
  }
  & .apb-envelope-meter { margin-top: 14px; display: grid; gap: 7px;
    & .apb-envelope-fill { height: 8px; }
    & p { margin: 0; display: flex; justify-content: space-between; gap: 8px; font-size: 12px; color: var(--apb-envelope-mute); font-variant-numeric: tabular-nums; }
    & p b { color: var(--apb-envelope-ink); font-weight: 650; }
    & p + p { margin-top: -4px; }
  }
  & .apb-envelope-sec { padding: 14px 18px; border-bottom: 1px solid var(--apb-envelope-line);
    & h4 { margin: 0 0 10px; font-size: 11px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--apb-envelope-mute); display: flex; justify-content: space-between; }
  }
  & .apb-envelope-need { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 11px; background: color-mix(in oklch, var(--apb-envelope-gold) 22%, var(--apb-envelope-bg));
    & p { margin: 0; font-size: 13px; text-wrap: pretty; }
    &.is-ok { background: var(--apb-envelope-tint); }
    &.is-over { background: color-mix(in oklch, var(--apb-envelope-warn) 14%, var(--apb-envelope-bg)); }
  }
  & .apb-envelope-target { display: flex; align-items: center; gap: 6px;
    & > span { flex: 1; font-size: 13px; }
    & input { width: 96px; height: 32px; padding: 0 8px; border: 1px solid var(--apb-envelope-line2); border-radius: 8px; background: var(--apb-envelope-bg); text-align: right; font-variant-numeric: tabular-nums; }
    & input:focus { outline: 0; border-color: var(--apb-envelope-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apb-envelope-accent) 18%, transparent); }
  }
  & .apb-envelope-quick { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-top: 10px;
    & button { display: grid; gap: 1px; padding: 8px 10px; border-radius: 10px; text-align: left; background: var(--apb-envelope-sunk); transition: background-color .18s, transform .18s var(--apb-envelope-ease); }
    & button:hover:not(:disabled) { background: color-mix(in oklch, var(--apb-envelope-ink) 9%, var(--apb-envelope-bg)); }
    & button:active:not(:disabled) { transform: scale(.98); }
