/* ── Larder · envelope budget. Integer cents everywhere; every figure is derived, never stored ── */
const ID = 'apb-envelope';
const fmt = (c, plus) => (c < 0 ? '−' : plus && c > 0 ? '+' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const raw = c => (c / 100).toFixed(2);
/* "650", "1,200.50", "120+35-10", and "+40" to add to what is there. Never eval. */
function parseAmt(str, current) {
  let s = String(str).replace(/[$,\s]/g, '').replace(/−/g, '-');
  if (!s) return 0;
  const rel = /^[+-]/.test(s) && current !== undefined;
  if (!/^[-+]?(\d+\.?\d*|\.\d+)([-+](\d+\.?\d*|\.\d+))*$/.test(s)) return null;
  let total = 0;
  s.replace(/[-+]?(\d+\.?\d*|\.\d+)/g, m => { total += Math.round(parseFloat(m) * 100); return m; });
  return rel ? current + total : total;
}

const GROUPS = [
  { k: 'bills', n: 'Bills', c: 'var(--apb-envelope-g1)' },
  { k: 'day', n: 'Everyday', c: 'var(--apb-envelope-g2)' },
