/* aug = balance carried out of August; sep = [assigned, spent]; oct = assigned; tx = October activity */
const ENV = [
  { k: 'rent', n: 'Rent', g: 'bills', t: 215000, aug: 0, sep: [215000, -215000], oct: 215000, tx: [['Oct 1', 'Wexford Property Mgmt', -215000]] },
  { k: 'power', n: 'Electric & gas', g: 'bills', t: 14000, aug: 0, sep: [14000, -12640], oct: 13000, tx: [], hint: 'Bill lands Oct 19' },
