  { k: 'move', n: 'Transport', g: 'day', t: 16000, aug: 0, sep: [16000, -14160], oct: 14000, tx: [['Oct 3', 'Ridgeline Fuel', -5280], ['Oct 7', 'Transit card reload', -4000]] },
  { k: 'home', n: 'Household', g: 'day', t: 9000, aug: 0, sep: [9000, -5895], oct: 9000, tx: [['Oct 5', 'Brightwick Hardware', -2748]] },
  { k: 'fix', n: 'Car repairs', g: 'goals', t: 7500, aug: 33700, sep: [7500, 0], oct: 7500, tx: [] },
  { k: 'gift', n: 'Holiday gifts', g: 'goals', t: 20000, aug: 0, sep: [20000, 0], oct: 20000, tx: [], hint: '$600 by Dec 1' },
  { k: 'rainy', n: 'Emergency fund', g: 'goals', t: 30000, aug: 437800, sep: [47200, 0], oct: 30000, tx: [], hint: 'Goal $9,000 · 3 months of costs' },
  { k: 'climb', n: 'Climbing gym', g: 'fun', t: 6200, aug: 0, sep: [6200, -6200], oct: 6200, tx: [['Oct 1', 'Basalt Climbing Co.', -6200]] },
  { k: 'books', n: 'Books & records', g: 'fun', t: 4000, aug: 0, sep: [4000, -2725], oct: 0, tx: [['Oct 8', 'Tidewater Records', -2499]] }
];
const BY = Object.fromEntries(ENV.map(e => [e.k, e]));
const MONTHS = [
  { n: 'September 2026', s: 'September', state: 'Closed', inc: 455200, closed: true },
  { n: 'October 2026', s: 'October', state: 'This month', inc: 455200 },
  { n: 'November 2026', s: 'November', state: 'Planning ahead', inc: 0 }
