const S = {
  m: 1, sel: 'groc', filter: 'all', q: '', collapsed: new Set(), view: 'list',
  A: [Object.fromEntries(ENV.map(e => [e.k, e.sep[0]])), Object.fromEntries(ENV.map(e => [e.k, e.oct])), Object.fromEntries(ENV.map(e => [e.k, 0]))],
