  moves: [[], [], []]
};
const hist = [];

const spent = (m, k) => m === 0 ? BY[k].sep[1] : m === 1 ? BY[k].tx.reduce((s, x) => s + x[2], 0) : 0;
function avail(m, k) { let v = BY[k].aug; for (let i = 0; i <= m; i++) v += S.A[i][k] + spent(i, k); return v; }
const carryIn = (m, k) => avail(m, k) - S.A[m][k] - spent(m, k);
