      <div class="${ID}-spread"><div class="${ID}-bar" aria-hidden="true">${GROUPS.map(g => `<i style="--c:${g.c}" data-seg="${g.k}"></i>`).join('')}<i data-seg="left"></i></div><div class="${ID}-legend">${GROUPS.map(g => `<span style="--c:${g.c}" data-leg="${g.k}"></span>`).join('')}</div></div>
      <button type="button" class="${ID}-btn is-accent" data-act="auto">${I.wand}<span data-f="autol">Fund underfunded</span> <kbd>A</kbd></button>`;
  }
