  else if (over) needBox = `<div class="${ID}-need is-over"><p>Overspent by <b>${fmt(-a)}</b>. Cover it before the month ends.</p><button type="button" class="${ID}-btn" data-act="fund" ${r < n ? `disabled title="Only ${fmt(Math.max(r, 0))} ready to assign. Drag money in from another envelope."` : ''}>Cover ${fmt(n)}</button></div>`;
