  if (m === 1) tx += e.tx.slice().reverse().map(x => `<li><time>${x[0]}</time><span>${esc(x[1])}</span><b>${fmt(x[2])}</b></li>`).join('');
  tx += S.moves[m].filter(v => v.from === k || v.to === k).reverse().map(v => `<li class="is-move"><time>Now</time><span>${v.to === k ? 'Moved from ' + esc(v.from === 'rta' ? 'Ready to assign' : BY[v.from].n) : 'Moved to ' + esc(v.to === 'rta' ? 'Ready to assign' : BY[v.to].n)}</span><b>${fmt(v.to === k ? v.amt : -v.amt, true)}</b></li>`).join('');
