function update() {
  const keys = ENV.filter(e => !S.collapsed.has(e.g) && filterOk(e.k)).map(e => e.k).join();
  if (keys !== shownKeys) renderGrid(); else paint();
}

/* ── actions ── */
function setAssigned(k, v, label) {
  const m = S.m;
  if (MONTHS[m].closed || v === S.A[m][k]) return;
  commit(label || 'Assigned ' + fmt(v) + ' to ' + BY[k].n, () => { S.A[m][k] = v; });
}
function select(k, focusCol) {
  if (!BY[k]) return;
  S.sel = k;
  paint();
