    const row = $(`.${ID}-row[data-k="${k}"]`);
    const el = row && row.querySelector(`[data-col="${focusCol}"]`);
    if (el && el.offsetParent) { el.focus({ preventScroll: true }); reveal(row); }
  }
}
function reveal(n) {
  const sc = $(`.${ID}-scroller`), pr = sc.getBoundingClientRect(), r = n.getBoundingClientRect();
  const d = r.top < pr.top + 44 ? r.top - pr.top - 44 : r.bottom > pr.bottom - 8 ? r.bottom - pr.bottom + 8 : 0;
  if (d) sc.scrollBy({ top: d, behavior: RM.matches ? 'auto' : 'smooth' });
}
function autoFund() {
  const m = S.m;
  let left = rta(m);
  if (MONTHS[m].closed || left <= 0) return;
  const plan = [];
  for (const e of ENV) { const n = need(m, e.k); if (n && left > 0) { const v = Math.min(n, left); plan.push([e.k, v]); left -= v; } }
  if (!plan.length) return;
  const tot = plan.reduce((s, p) => s + p[1], 0);
  commit('Funded ' + plan.length + ' envelopes with ' + fmt(tot), () => plan.forEach(([k, v]) => { S.A[m][k] += v; }));
  plan.forEach(([k], i) => setTimeout(() => coin($(`[data-drop="rta"]`), availEl(k)), i * 90));
}
const availEl = k => k === 'rta' ? $('[data-f="rta"]') : $(`.${ID}-row[data-k="${k}"] [data-f="avail"]`);

/* a little money changes hands: coins arc from the source to the destination */
function coin(a, b) {
  if (!a || !b) return;
  const pulse = () => { b.classList.remove('is-pulse'); void b.offsetWidth; b.classList.add('is-pulse'); };
  if (RM.matches) { pulse(); return; }
  const rr = root.getBoundingClientRect(), ox = rr.left + root.clientLeft, oy = rr.top + root.clientTop;
  const A = a.getBoundingClientRect(), B = b.getBoundingClientRect();
  const x0 = A.left + A.width / 2 - ox, y0 = A.top + A.height / 2 - oy, x1 = B.left + B.width / 2 - ox, y1 = B.top + B.height / 2 - oy;
  const lift = Math.min(140, Math.abs(y1 - y0) * .35 + Math.abs(x1 - x0) * .15 + 36);
  for (let c = 0; c < 3; c++) {
    const el = root.ownerDocument.createElement('i');
    el.className = ID + '-coin'; el.textContent = '$'; el.setAttribute('aria-hidden', 'true');
    root.appendChild(el);
