}

/* ── move-money panel ── */
let popCtx = null;
function openMove(from, to, anchor) {
  const m = S.m;
  if (MONTHS[m].closed) return;
  from = from || S.sel;
  const opts = sel => `<option value="rta" ${sel === 'rta' ? 'selected' : ''}>Ready to assign · ${fmt(rta(m))}</option>` + GROUPS.map(g => `<optgroup label="${g.n}">${ENV.filter(e => e.g === g.k).map(e => `<option value="${e.k}" ${sel === e.k ? 'selected' : ''}>${esc(e.n)} · ${fmt(avail(m, e.k))}</option>`).join('')}</optgroup>`).join('');
