  if (!to) to = from === 'rta' ? S.sel : 'rta';
  const srcAvail = from === 'rta' ? rta(m) : avail(m, from);
  const dstNeed = to === 'rta' ? 0 : need(m, to);
  const amt = Math.max(0, dstNeed ? Math.min(dstNeed, srcAvail) : srcAvail);
  pop.innerHTML = `<form data-move novalidate>
    <h4>${I.move}Move money</h4>
    <label>Amount<input data-mamt inputmode="decimal" autocomplete="off" value="${raw(amt)}"></label>
    <div class="${ID}-pair"><label>From<select data-mfrom>${opts(from)}</select></label>${I.arrow}<label>To<select data-mto>${opts(to)}</select></label></div>
    <p class="${ID}-err" data-merr role="alert"></p>
    <div class="${ID}-row2"><button type="button" class="${ID}-btn is-soft" data-act="mclose">Cancel <kbd>Esc</kbd></button><button type="submit" class="${ID}-btn is-accent">Move <kbd>↵</kbd></button></div>
  </form>`;
  pop.hidden = false;
  popCtx = { anchor: anchor || availEl(to === 'rta' ? from : to) };
  placePop(popCtx.anchor);
  const inp = $('[data-mamt]', pop);
  inp.focus({ preventScroll: true }); inp.select();
}
function placePop(anchor) {
  const rr = root.getBoundingClientRect(), pw = pop.offsetWidth, ph = pop.offsetHeight;
  let x = (rr.width - pw) / 2, y = (rr.height - ph) / 2, ox = '50%';
  if (anchor && anchor.isConnected && rr.width > 760) {
    const b = anchor.getBoundingClientRect();
    x = Math.min(rr.width - pw - 12, Math.max(12, b.left - rr.left + b.width / 2 - pw / 2));
    y = b.bottom - rr.top + 8;
    if (y + ph > rr.height - 12) y = Math.max(12, b.top - rr.top - ph - 8);
    ox = Math.round(b.left - rr.left + b.width / 2 - x) + 'px';
