}
function submitMove() {
  const m = S.m, f = $('[data-mfrom]', pop).value, t = $('[data-mto]', pop).value, err = $('[data-merr]', pop);
  const amt = parseAmt($('[data-mamt]', pop).value);
  const src = f === 'rta' ? rta(m) : avail(m, f), name = k => k === 'rta' ? 'Ready to assign' : BY[k].n;
  let msg = '';
  if (amt === null) msg = 'Enter an amount like 40 or 12.50.';
  else if (amt <= 0) msg = 'Enter an amount above zero.';
  else if (f === t) msg = 'Choose two different places.';
  else if (src <= 0) msg = name(f) + ' has nothing available to move.';
  else if (amt > src) msg = 'Only ' + fmt(src) + ' available in ' + name(f) + '.';
  if (msg) { err.textContent = msg; $('[data-mamt]', pop).focus(); return; }
  const a = availEl(f), b = availEl(t);
  closePop(false);
  commit('Moved ' + fmt(amt) + ' from ' + name(f) + ' to ' + name(t), () => {
    if (f !== 'rta') S.A[m][f] -= amt;
    if (t !== 'rta') S.A[m][t] += amt;
    S.moves[m].push({ from: f, to: t, amt });
  });
  coin(a && a.isConnected ? a : availEl(f), b && b.isConnected ? b : availEl(t));
}

/* ── drag an Available pill onto another envelope ── */
let drag = null, swallowClick = false;
root.addEventListener('pointerdown', e => {
  const b = e.target.closest(`.${ID}-avail`);
  if (!b || b.disabled || e.button !== 0) return;
  const row = b.closest(`.${ID}-row`);
  drag = { k: row.dataset.k, x: e.clientX, y: e.clientY, on: false, over: null, el: b };
  try { b.setPointerCapture(e.pointerId); } catch (_) {}
});
root.addEventListener('pointermove', e => {
  if (!drag) return;
  if (!drag.on) {
    if (Math.hypot(e.clientX - drag.x, e.clientY - drag.y) < 6) return;
    drag.on = true;
    ghost.textContent = BY[drag.k].n + ' · ' + fmt(avail(S.m, drag.k));
    ghost.hidden = false;
    drag.el.closest(`.${ID}-row`).classList.add('is-source');
  }
  const rr = root.getBoundingClientRect();
  ghost.style.transform = `translate(${e.clientX - rr.left + 12}px, ${e.clientY - rr.top + 10}px) rotate(-3deg)`;
  drag.cx = e.clientX; drag.cy = e.clientY;
  /* near the scroller's edges, scroll it so far-away envelopes are reachable */
