  drag.vy = e.clientY > sr.bottom - 48 ? Math.min(14, (e.clientY - sr.bottom + 48) / 3) : e.clientY < sr.top + 48 ? -Math.min(14, (sr.top + 48 - e.clientY) / 3) : 0;
