  ghost.hidden = true;
  $$(`.is-source, .is-over`).forEach(n => n.classList.remove('is-source', 'is-over'));
  rtaEl.classList.remove('is-target');
  if (d.on) {
    swallowClick = true; setTimeout(() => { swallowClick = false; }, 0);
    if (drop && d.over) openMove(d.k, d.over.dataset.drop, d.over.dataset.drop === 'rta' ? $('[data-f="rta"]') : d.over.querySelector('[data-f="avail"]'));
  }
}
root.addEventListener('pointerup', () => endDrag(true));
root.addEventListener('pointercancel', () => endDrag(false));

/* ── clicks ── */
root.addEventListener('click', e => {
  const b = e.target.closest('[data-act], [data-filter]');
  if (!pop.hidden && !e.target.closest('[data-pop]') && !e.target.closest(`.${ID}-avail`)) closePop(false);
  if (!b || !root.contains(b)) return;
  if (b.dataset.filter) { S.filter = b.dataset.filter; renderGrid(); return; }
  const act = b.dataset.act, row = b.closest(`.${ID}-row`);
  switch (act) {
    case 'sel': select(row.dataset.k); S.view = 'detail'; root.dataset.view = 'detail'; break;
    case 'avail':
      if (swallowClick) return;
      S.sel = row.dataset.k; paint(); openMove(row.dataset.k, null, b); break;
    case 'group': S.collapsed.has(b.dataset.g) ? S.collapsed.delete(b.dataset.g) : S.collapsed.add(b.dataset.g); renderGrid(); break;
    case 'prev': case 'next': month(act === 'prev' ? -1 : 1); break;
    case 'undo': undo(); break;
    case 'auto': autoFund(); break;
    case 'fund': { const n = need(S.m, S.sel); setAssigned(S.sel, S.A[S.m][S.sel] + n, (avail(S.m, S.sel) < 0 ? 'Covered ' : 'Assigned ') + fmt(n) + ' to ' + BY[S.sel].n); coin($('[data-f="rta"]'), availEl(S.sel)); break; }
    case 'quick': setAssigned(S.sel, +b.dataset.v); break;
    case 'tstep': { const k = S.sel, v = Math.max(0, S.T[k] + +b.dataset.d); commit('Set ' + BY[k].n + ' target to ' + fmt(v), () => { S.T[k] = v; }); break; }
    case 'move': openMove(S.sel); break;
    case 'mclose': closePop(true); break;
    case 'back': S.view = 'list'; root.dataset.view = 'list'; select(S.sel, 0); break;
