});
function month(d) {
  const m = Math.max(0, Math.min(MONTHS.length - 1, S.m + d));
  if (m === S.m) return;
  S.m = m; closePop(false);
  renderGrid();
}

/* ── inputs ── */
root.addEventListener('submit', e => { e.preventDefault(); if (e.target.matches('[data-move]')) submitMove(); });
function commitAmt(inp) {
  const k = inp.dataset.amt, v = parseAmt(inp.value, S.A[S.m][k]);
  if (v === null) { inp.value = raw(S.A[S.m][k]); toast('“' + esc(inp.value) + '” is not an amount. Try 40 or +40.'); return; }
  setAssigned(k, v);
}
root.addEventListener('focusin', e => { if (e.target.dataset.amt) { e.target.value = raw(S.A[S.m][e.target.dataset.amt]); requestAnimationFrame(() => { if (!root.isConnected) return; e.target.select(); }); S.sel = e.target.dataset.amt; paint(); } });
root.addEventListener('focusout', e => { const t = e.target; if (t.dataset.amt && !t.dataset.skip) commitAmt(t); delete t.dataset.skip; if (t.matches('[data-target]')) commitTarget(t); });
function commitTarget(inp) {
  const k = S.sel, v = parseAmt(inp.value, S.T[k]);
  if (v === null || v < 0) { inp.value = raw(S.T[k]); return; }
