}
$('[data-search]').addEventListener('input', e => { S.q = e.target.value.trim(); renderGrid(); });

/* ── keyboard ── */
function rowStep(d, col) {
  const rows = $$(`.${ID}-row`);
  const i = rows.findIndex(r => r.dataset.k === S.sel);
  const n = rows[Math.max(0, Math.min(rows.length - 1, (i < 0 ? 0 : i) + d))];
  if (n) select(n.dataset.k, col);
}
root.addEventListener('keydown', e => {
  const t = e.target, typing = t.matches('input, select, textarea');
  const k = e.key;
