    if (t.matches('[data-search]') && t.value) { t.value = ''; S.q = ''; renderGrid(); return; }
    if (S.view === 'detail') { S.view = 'list'; root.dataset.view = 'list'; select(S.sel, 0); }
    return;
  }
  if (t.dataset.amt) {
    if (k === 'Enter') { e.preventDefault(); commitAmt(t); t.value = raw(S.A[S.m][t.dataset.amt]); t.select(); }
    else if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); t.blur(); rowStep(k === 'ArrowDown' ? 1 : -1, 1); }
    return;
  }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const col = t.dataset && t.dataset.col !== undefined ? +t.dataset.col : 0;
  if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); rowStep(k === 'ArrowDown' ? 1 : -1, col); }
  else if (k === 'ArrowRight' && t.closest(`.${ID}-row`)) { e.preventDefault(); select(S.sel, Math.min(2, col + 1)); }
  else if (k === 'ArrowLeft' && t.closest(`.${ID}-row`)) { e.preventDefault(); select(S.sel, Math.max(0, col - 1)); }
  else if (k === 'Enter' && t.dataset.act === 'sel') { e.preventDefault(); const inp = $(`[data-amt="${S.sel}"]`); if (inp && inp.offsetParent && !inp.disabled) inp.focus(); else { S.view = 'detail'; root.dataset.view = 'detail'; paint(); } }
  else if (k === '/') { e.preventDefault(); $('[data-search]').focus(); }
  else if (k === 'm' || k === 'M') { e.preventDefault(); openMove(S.sel); }
  else if (k === 'a' || k === 'A') { e.preventDefault(); autoFund(); }
  else if (k === '[') month(-1);
  else if (k === ']') month(1);
});

renderGrid();

css:
@keyframes apb-rules-spin { to { transform: rotate(360deg); } }
@keyframes apb-rules-edge { from { box-shadow: 0 1px 0 transparent; } to { box-shadow: 0 1px 0 var(--apb-rules-line), 0 14px 20px -18px black; } }
@keyframes apb-rules-pop { 0% { transform: scale(.6); opacity: 0; } 60% { transform: scale(1.08); opacity: 1; } 100% { transform: scale(1); } }
@property --apb-rules-glow { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@keyframes apb-rules-scan { from { --apb-rules-glow: 0%; } to { --apb-rules-glow: 100%; } }

.apb-rules {
  --apb-rules-bg: oklch(0.2 0.008 115);
  --apb-rules-ink: oklch(0.95 0.012 110);
  --apb-rules-accent: oklch(0.9 0.18 122);
  --apb-rules-warn: oklch(0.72 0.16 28);
  --apb-rules-raise: color-mix(in oklch, var(--apb-rules-ink) 4%, var(--apb-rules-bg));
  --apb-rules-raise2: color-mix(in oklch, var(--apb-rules-ink) 8%, var(--apb-rules-bg));
  --apb-rules-deep: color-mix(in oklch, black 22%, var(--apb-rules-bg));
  --apb-rules-line: color-mix(in oklch, var(--apb-rules-ink) 10%, transparent);
  --apb-rules-line2: color-mix(in oklch, var(--apb-rules-ink) 18%, transparent);
  --apb-rules-mute: color-mix(in oklch, var(--apb-rules-ink) 58%, var(--apb-rules-bg));
  --apb-rules-faint: color-mix(in oklch, var(--apb-rules-ink) 38%, var(--apb-rules-bg));
  --apb-rules-on: color-mix(in oklch, var(--apb-rules-accent) 14%, var(--apb-rules-bg));
  --apb-rules-ease: cubic-bezier(.2, .8, .2, 1);
  --apb-rules-spring: linear(0, .08 4%, .3 9%, .6 15%, .86 21%, 1.01 27%, 1.06 33%, 1.05 39%, 1.01 48%, .995 60%, 1);
  --apb-rules-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; box-sizing: border-box; width: 100%; height: var(--apb-rules-h, 680px);
  container-type: inline-size; container-name: apb-rules;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apb-rules-line);
  background: var(--apb-rules-bg); color: var(--apb-rules-ink);
  font: 13.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--apb-rules-accent);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & svg { display: block; width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apb-rules-accent); outline-offset: 2px; border-radius: 6px; }
  & kbd { display: inline-block; font: 600 10.5px/1 var(--apb-rules-mono); padding: 3px 5px; min-width: 17px; text-align: center; border-radius: 4px; background: var(--apb-rules-raise2); color: var(--apb-rules-mute); box-shadow: inset 0 -1px 0 var(--apb-rules-line2); }
  & code { font-family: var(--apb-rules-mono); font-size: .92em; letter-spacing: -.01em; }
  & mark { background: color-mix(in oklch, var(--apb-rules-accent) 26%, transparent); color: var(--apb-rules-accent); border-radius: 3px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--apb-rules-accent) 30%, transparent); }

  & .apb-rules-app { display: grid; height: 100%; grid-template-columns: 228px minmax(0, 1fr) 330px; grid-template-areas: "rail list insp"; }

  /* ── rail ── */
  & .apb-rules-rail { grid-area: rail; display: flex; flex-direction: column; gap: 6px; padding: 16px 12px; background: var(--apb-rules-deep); border-right: 1px solid var(--apb-rules-line); overflow: auto; overscroll-behavior: contain; scrollbar-width: none;
    & h3 { margin: 18px 6px 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apb-rules-faint); }
  }
  & .apb-rules-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 14px;
    & svg { width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: var(--apb-rules-accent); color: var(--apb-rules-bg); stroke-width: 2; }
    & b { display: block; font-size: 15px; font-weight: 780; letter-spacing: -.01em; }
    & span { display: block; font-size: 11.5px; color: var(--apb-rules-mute); }
  }
  & .apb-rules-queues { display: grid; gap: 2px;
    & button { display: flex; align-items: center; justify-content: space-between; height: 34px; padding: 0 10px; border-radius: 9px; font-weight: 560; color: var(--apb-rules-mute); transition: background-color .18s, color .18s; }
    & button:hover { background: var(--apb-rules-raise); color: var(--apb-rules-ink); }
    & button[aria-selected="true"] { background: var(--apb-rules-raise2); color: var(--apb-rules-ink); }
    & i { font-style: normal; font-size: 11.5px; font-variant-numeric: tabular-nums; padding: 1px 7px; border-radius: 99px; background: var(--apb-rules-line); }
