  }
  & .apb-rules-cats { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px;
    & li { position: relative; display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 6px 6px 8px; border-radius: 8px; }
    & kbd { color: oklch(0.84 0.11 var(--h)); background: oklch(0.84 0.11 var(--h) / .12); box-shadow: none; }
    & span { font-size: 12.5px; line-height: 1.2; min-width: 0; }
    & small { display: block; font-size: 11px; color: var(--apb-rules-faint); }
    & b { font-size: 12px; font-weight: 600; font-variant-numeric: tabular-nums; }
    & i { position: absolute; left: 34px; right: 6px; bottom: 3px; height: 2px; border-radius: 2px; background: oklch(0.84 0.11 var(--h) / .7); transform-origin: left; transform: scaleX(var(--p)); transition: transform .7s var(--apb-rules-spring); }
  }

  /* ── list ── */
  & .apb-rules-list { grid-area: list; display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; timeline-scope: --apb-rules-sc; }
  & .apb-rules-lhead { position: relative; z-index: 2; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title tools" "mtabs mtabs"; align-items: center; gap: 10px; padding: 16px 18px 14px; background: var(--apb-rules-bg); }
  @supports (animation-timeline: scroll()) {
