  }
  & .apb-rules-title { grid-area: title; min-width: 0;
    & h2 { margin: 0; font-size: clamp(17px, 1.1cqi + 6px, 21px); font-weight: 760; letter-spacing: -.02em; text-wrap: balance; }
    & p { margin: 2px 0 0; font-size: 12px; color: var(--apb-rules-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .apb-rules-tools { grid-area: tools; display: flex; align-items: center; gap: 6px; }
  & .apb-rules-mtabs { grid-area: mtabs; display: none; gap: 4px; overflow-x: auto; scrollbar-width: none;
    & button { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--apb-rules-mute); white-space: nowrap; background: var(--apb-rules-raise); }
    & button[aria-selected="true"] { background: var(--apb-rules-ink); color: var(--apb-rules-bg); }
    & i { font-style: normal; font-size: 11px; opacity: .75; font-variant-numeric: tabular-nums; }
  }
  & .apb-rules-progress { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--apb-rules-line);
    & i { position: absolute; inset: 0; background: linear-gradient(90deg, color-mix(in oklch, var(--apb-rules-accent) 40%, transparent), var(--apb-rules-accent)); transform-origin: left; transform: scaleX(var(--p, 0)); transition: transform .8s var(--apb-rules-spring); }
  }
  & .apb-rules-search { display: flex; align-items: center; gap: 7px; height: 32px; width: 210px; padding: 0 7px 0 9px; border-radius: 9px; background: var(--apb-rules-raise); border: 1px solid var(--apb-rules-line); color: var(--apb-rules-mute); transition: border-color .2s, width .3s var(--apb-rules-ease);
    &:focus-within { border-color: color-mix(in oklch, var(--apb-rules-accent) 60%, transparent); width: 250px; }
    & svg { width: 15px; height: 15px; }
    & input { flex: 1; min-width: 0; background: none; border: 0; outline: 0; font-size: 13px; color: var(--apb-rules-ink); }
    & input::placeholder { color: var(--apb-rules-faint); }
    & input::-webkit-search-cancel-button { display: none; }
  }
  & .apb-rules-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: 9px; font-size: 13px; font-weight: 620; white-space: nowrap; background: var(--apb-rules-raise2); color: var(--apb-rules-ink); transition: background-color .18s, transform .18s var(--apb-rules-ease), color .18s;
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--apb-rules-ink) 14%, var(--apb-rules-bg)); }
    &:active:not(:disabled) { transform: scale(.97); }
    &.is-accent { background: var(--apb-rules-accent); color: oklch(0.2 0.03 120); &:hover:not(:disabled) { background: color-mix(in oklch, var(--apb-rules-accent) 86%, white); } & kbd { background: oklch(0.2 0.03 120 / .14); color: inherit; box-shadow: none; } }
    &.is-ghost { background: transparent; color: var(--apb-rules-mute); }
    &.is-danger { color: var(--apb-rules-warn); }
    &.is-busy svg { animation: apb-rules-spin .9s linear infinite; }
  }
  & .apb-rules-ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--apb-rules-mute); transition: background-color .18s, color .18s;
    &:hover:not(:disabled) { background: var(--apb-rules-raise2); color: var(--apb-rules-ink); }
    &.is-sm { width: 26px; height: 26px; border-radius: 7px; & svg { width: 15px; height: 15px; } }
  }
  & .apb-rules-bulk { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 0 12px 8px; padding: 8px 8px 8px 14px; border-radius: 12px; background: var(--apb-rules-on); border: 1px solid color-mix(in oklch, var(--apb-rules-accent) 30%, transparent);
    transition: opacity .25s var(--apb-rules-ease), transform .35s var(--apb-rules-spring), display .35s allow-discrete;
    @starting-style { opacity: 0; transform: translateY(-6px); }
