  }
  & .apb-rules-scroll { overflow: auto; overscroll-behavior: contain; padding: 4px 10px 16px; scroll-timeline: --apb-rules-sc block; scrollbar-width: thin; scrollbar-color: var(--apb-rules-line2) transparent; }
  & .apb-rules-row, & .apb-rules-rule { position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr) auto 104px; align-items: center; gap: 8px; padding: 4px 10px 4px 4px; border-radius: 11px; transition: background-color .15s;
    &:hover { background: var(--apb-rules-raise); }
    &[data-cur] { background: var(--apb-rules-raise2); }
    &[data-cur]::before { content: ""; position: absolute; left: -6px; top: 10px; bottom: 10px; width: 3px; border-radius: 3px; background: var(--apb-rules-accent); }
    &[aria-selected="true"] { background: var(--apb-rules-on); }
    &.is-match { background: color-mix(in oklch, var(--apb-rules-accent) 9%, var(--apb-rules-bg)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apb-rules-accent) 40%, transparent); }
  }
