  }
  & .apb-rules-row.is-match .apb-rules-main small { color: var(--apb-rules-accent); }
  & .apb-rules-cc { display: flex; align-items: center; gap: 2px; justify-content: flex-end; }
  & .apb-rules-sug, & .apb-rules-chip { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px 0 4px; border-radius: 8px; font-size: 12px; font-weight: 600; white-space: nowrap; color: oklch(0.86 0.1 var(--h)); }
