const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = v => String(v).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
/* FLIP: measure keyed children, mutate, then play every move from where it was */
function flip(list, mutate, o) {
  const first = new Map(list().map(e => [e.dataset.k, e.getBoundingClientRect()]));
  mutate();
  if (RM.matches) return;
  list().forEach((e, i) => {
    const f = first.get(e.dataset.k), l = e.getBoundingClientRect();
    if (!f) { e.animate([{ opacity: 0, transform: 'translateY(6px) scale(.98)' }, { opacity: 1, transform: 'none' }], { duration: 320, delay: (o && o.stagger || 0) * i, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' }); return; }
    const dx = f.left - l.left, dy = f.top - l.top;
    if (Math.abs(dx) + Math.abs(dy) > .5) e.animate([{ transform: `translate(${dx}px,${dy}px)` }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
/* one toast at a time, inside the root, with an optional Undo */
let toastT = 0;
function toast(msg, undo) {
  const t = $('[data-toast]');
  if (!t) return;
  clearTimeout(toastT);
  t.innerHTML = '<span>' + msg + '</span>' + (undo ? '<button type="button" data-toast-undo>Undo <kbd>' + MOD + ' Z</kbd></button>' : '');
  t.hidden = false; t.classList.remove('is-in'); void t.offsetWidth; t.classList.add('is-in');
  const b = t.querySelector('[data-toast-undo]');
  if (b) b.onclick = () => { undo(); hideToast(); };
  toastT = setTimeout(hideToast, undo ? 6000 : 3200);
}
function hideToast() { const t = $('[data-toast]'); if (t) { t.classList.remove('is-in'); t.hidden = true; } }

/* ── Ledgerwick · review queue. Rules are data: a draft rule is matched live against the queue ── */
const ID = 'apb-rules';
const fmt = (c, sign) => (c < 0 ? '−' : sign && c > 0 ? '+' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const CATS = [
  { k: 'soft', n: 'Software & assets', h: 205 }, { k: 'travel', n: 'Travel', h: 72 }, { k: 'meals', n: 'Meals', h: 34 },
  { k: 'contract', n: 'Contractors', h: 318 }, { k: 'office', n: 'Office supplies', h: 152 }, { k: 'mkt', n: 'Marketing', h: 0 },
  { k: 'income', n: 'Client income', h: 125 }, { k: 'bank', n: 'Bank fees', h: 255 }, { k: 'draw', n: 'Owner’s draw', h: 96 }
];
const CAT = Object.fromEntries(CATS.map((c, i) => [c.k, { ...c, i: i + 1 }]));
const T = (k, d, raw, amt, sug, conf, extra) => ({ k, d, raw, amt, sug, conf, cat: null, name: null, ex: false, rule: null, ...extra });
const S = {
  q: 'review', cur: 't3', sel: new Set(), search: '', draft: null, rsel: 'r1', synced: false, view: 'list', menu: null,
  txs: [
    T('h1', 'Oct 1', 'ACH CR NORTHFOLD PRESS INV-0398', 360000, 'income', 99, { cat: 'income', name: 'Northfold Press', rule: 'r1' }),
    T('t1', 'Oct 1', 'VECTORLY*TEAM PLAN 2 SEATS', -4800, 'soft', 94),
    T('t2', 'Oct 1', 'CLOUDHARBOR HOSTING INV 88213', -2400, 'soft', 91),
