    T('t3', 'Oct 2', 'POS FERN&FIG CAFE #4471 PORTLAND OR', -1240, 'meals', 72),
    T('t4', 'Oct 2', 'RIDEWAY *TRIP 10-02 HELP.RIDEWAY', -1875, 'travel', 88),
    T('t5', 'Oct 3', 'ACH CR MARLOWE HOTEL GRP INV-0412', 480000, 'income', 97),
    T('t6', 'Oct 3', 'POS FERN&FIG CAFE #4471 PORTLAND OR', -980, 'meals', 72),
    T('x1', 'Oct 3', 'TRANSFER FROM SAV 3310', 100000, null, 0, { ex: true, name: 'Transfer from savings' }),
    T('t7', 'Oct 4', 'SKYWARD AIR 0162384 SEA', -34260, 'travel', 90),
    T('h3', 'Oct 4', 'ACH CR NORTHFOLD PRESS INV-0402', 120000, 'income', 99, { cat: 'income', name: 'Northfold Press', rule: 'r1' }),
