    T('t11', 'Oct 6', 'POS PAPERWORKS SUPPLY CO PDX', -6418, 'office', 83),
    T('h4', 'Oct 6', 'POS HEARTH & HOLLOW BAKERY', -2340, 'meals', 80, { cat: 'meals', name: 'Hearth & Hollow' }),
    T('t12', 'Oct 7', 'INKWELL FONTS LICENSE 2231', -12000, 'soft', 77),
