    { id: 'r2', tokens: ['GREYLOCK'], dir: 'any', cat: 'mkt', name: 'Greylock Print', on: true }
  ]
};
const POOL = [
  T('n1', 'Oct 10', 'POS FERN&FIG CAFE #4471 PORTLAND OR', -1160, 'meals', 72),
  T('n2', 'Oct 10', 'RIDEWAY *TRIP 10-10 HELP.RIDEWAY', -2130, 'travel', 88),
  T('n3', 'Oct 10', 'VECTORLY*TEAM PLAN 3 SEATS', -7200, 'soft', 94),
  T('n4', 'Oct 10', 'ACH CR NORTHFOLD PRESS INV-0415', 96000, 'income', 99),
  T('n5', 'Oct 10', 'POS PAPERWORKS SUPPLY CO PDX', -2299, 'office', 83)
];
const STOP = new Set(['POS', 'ACH', 'CR', 'TO', 'TRIP', 'INV', 'ONLINE', 'TRANSFER', 'CHK', 'P2P', 'OR', 'PDX', 'SEA', 'CO', 'FROM', 'SAV']);
const tokens = raw => raw.split(/[\s*]+/).filter(Boolean);
const isWord = w => !STOP.has(w) && !/\d/.test(w) && !/^HELP\./.test(w);
function defaultTokens(raw) {
  const t = tokens(raw), i = t.findIndex(isWord);
  if (i < 0) return [t[0]];
  const n = t[i + 1];
  return n && isWord(n) && n.length > 2 ? [t[i], n] : [t[i]];
}
const title = s => s.toLowerCase().replace(/(^|[\s&\-.])([a-z])/g, (m, a, b) => a + b.toUpperCase());
const nameOf = t => t.name || title(defaultTokens(t.raw).join(' '));
const byK = k => S.txs.find(t => t.k === k);
const qOf = t => t.ex ? 'excluded' : t.cat ? 'done' : 'review';
const matches = (r, t) => r.tokens.length > 0 && r.tokens.every(w => t.raw.toUpperCase().includes(w)) && (r.dir === 'any' || (r.dir === 'out' ? t.amt < 0 : t.amt > 0));
const shown = () => S.txs.filter(t => qOf(t) === S.q && (!S.search || (t.raw + ' ' + nameOf(t)).toLowerCase().includes(S.search.toLowerCase())));
function marked(raw, toks) {
  const up = raw.toUpperCase(), hit = new Array(raw.length).fill(false);
  (toks || []).forEach(w => { let i = up.indexOf(w); while (i > -1) { for (let j = i; j < i + w.length; j++) hit[j] = true; i = up.indexOf(w, i + 1); } });
  let out = '', open = false;
  for (let i = 0; i < raw.length; i++) {
