  if (S.q === 'review') {
    const c = counts();
    return `<div class="${ID}-empty is-zero" role="row"><div role="gridcell"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="19"/><path d="m15 24.5 6 6 12-13"/></svg><b>All caught up</b><span>${c.done} categorised, ${c.excluded} excluded, ${S.rules.length} rules working for you.</span>${S.synced ? '' : `<button type="button" class="${ID}-btn is-accent" data-act="sync">Sync bank</button>`}</div></div>`;
  }
  return `<div class="${ID}-empty" role="row"><div role="gridcell"><b>Nothing ${S.q === 'done' ? 'categorised' : 'excluded'} yet</b><button type="button" class="${ID}-btn" data-q="review">Go to review</button></div></div>`;
}
const ruleText = r => `${r.tokens.map(w => `<code>${esc(w)}</code>`).join(' + ')}${r.dir === 'any' ? '' : r.dir === 'in' ? ' · money in' : ' · money out'}`;
const hits = r => S.txs.filter(t => t.rule === r.id).length;
const pending = r => S.txs.filter(t => qOf(t) === 'review' && matches(r, t)).length;
function renderRules() {
