    <button type="button" role="gridcell" class="${ID}-main" data-act="rsel"><span><b>If descriptor has ${ruleText(r)}</b><small>then ${esc(CAT[r.cat].n)}${r.name ? ', rename “' + esc(r.name) + '”' : ''}</small></span></button>
    <span role="gridcell" class="${ID}-hits">${hits(r)} sorted</span>
    <span role="gridcell"><button type="button" role="switch" class="${ID}-switch" data-act="rtoggle" aria-checked="${r.on}" aria-label="Rule active"><i></i></button></span>
  </div>`).join('') : `<div class="${ID}-empty" role="row"><div role="gridcell"><b>No rules yet</b><span>Pick a transaction and press R to make one from its descriptor.</span><button type="button" class="${ID}-btn" data-q="review">Go to review</button></div></div>`;
}

function renderInsp() {
