    `<div class="${ID}-pick" role="listbox" aria-label="Category">${CATS.map(c => `<button type="button" role="option" data-act="pick" data-c="${c.k}" style="--h:${c.h}" aria-selected="${t.cat === c.k}" tabindex="${c.k === cur ? 0 : -1}"><kbd>${CAT[c.k].i}</kbd>${esc(c.n)}${!t.cat && t.sug === c.k ? `<em>${t.conf}%</em>` : ''}</button>`).join('')}</div>`}</div>
