}

function render(animate) { renderChrome(); renderRows(animate); renderInsp(); }

/* ── actions ── */
function leaveThen(keys, fn) {
  const els = keys.map(k => $(`.${ID}-row[data-k="${k}"]`)).filter(Boolean);
  if (RM.matches || !els.length) { fn(); return; }
  els.forEach((el, i) => el.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(28px)', filter: 'blur(2px)' }], { duration: 220, delay: i * 25, easing: 'cubic-bezier(.4,0,.6,1)', fill: 'forwards' }));
  setTimeout(fn, 200 + Math.min(els.length, 8) * 25);
}
function nextAfter(keys) {
  const list = shown().map(t => t.k), i = list.indexOf(keys[keys.length - 1]);
  const rest = list.filter(k => !keys.includes(k));
  return rest.find(k => list.indexOf(k) > i) || rest[rest.length - 1] || null;
}
function categorise(keys, cat, label) {
  keys = keys.filter(k => byK(k) && !byK(k).ex);
