  const leaving = S.q === 'review', nxt = leaving ? nextAfter(keys) : S.cur;
  snap(label || (keys.length > 1 ? keys.length + ' transactions → ' : nameOf(byK(keys[0])) + ' → ') + CAT[cat].n);
  keys.forEach(k => { const t = byK(k); t.cat = cat; t.rule = null; });
  keys.forEach(k => S.sel.delete(k));
  const done = () => { if (nxt) S.cur = nxt; render(true); focusCur(); };
  leaving ? leaveThen(keys, done) : done();
  toast(esc(hist[hist.length - 1].label), undo);
}
function setExcluded(keys, ex) {
  keys = keys.filter(byK);
  if (!keys.length) return;
  const nxt = nextAfter(keys);
  snap((ex ? 'Excluded ' : 'Included ') + (keys.length > 1 ? keys.length + ' transactions' : nameOf(byK(keys[0]))));
  keys.forEach(k => { const t = byK(k); t.ex = ex; if (ex) { t.cat = null; t.rule = null; } S.sel.delete(k); });
  leaveThen(keys, () => { if (nxt) S.cur = nxt; render(true); focusCur(); });
  toast(esc(hist[hist.length - 1].label), undo);
}
function unreview(k) {
  const t = byK(k);
  if (!t || !t.cat) return;
  const nxt = nextAfter([k]);
  snap('Sent ' + nameOf(t) + ' back to review');
  t.cat = null; t.rule = null;
  leaveThen([k], () => { if (nxt) S.cur = nxt; render(true); focusCur(); });
  toast(esc(hist[hist.length - 1].label), undo);
}
function focusCur() {
  if (S.view === 'insp' && root.querySelector(`.${ID}-insp`).offsetParent && !$(`.${ID}-list`).offsetParent) return;
  const el = $(`.${ID}-row[data-cur] .${ID}-main, .${ID}-rule[data-cur] .${ID}-main`);
