}
function reveal(el) {
  const sc = $('[data-scroll]'), a = sc.getBoundingClientRect(), b = el.getBoundingClientRect();
  const d = b.top < a.top + 4 ? b.top - a.top - 4 : b.bottom > a.bottom - 4 ? b.bottom - a.bottom + 4 : 0;
  if (d) sc.scrollBy({ top: d, behavior: RM.matches ? 'auto' : 'smooth' });
}
function setCur(k, open) {
  S.cur = k;
  if (S.draft && S.draft.from !== k) S.draft = null;
  $$(`.${ID}-row`).forEach(r => { const on = r.dataset.k === k; on ? r.setAttribute('data-cur', '') : r.removeAttribute('data-cur'); r.querySelector(`.${ID}-main`).tabIndex = on ? 0 : -1; });
  renderRows(false); renderInsp();
  if (open) { S.view = 'insp'; root.dataset.view = 'insp'; }
}
function newDraft(k) {
