  S.cur = t.k;
  S.draft = { from: t.k, tokens: defaultTokens(t.raw), dir: t.amt > 0 ? 'in' : 'out', cat: t.cat || t.sug, name: nameOf(t) };
  renderRows(false); renderInsp();
  S.view = 'insp'; root.dataset.view = 'insp';
  const f = $('[data-act="tok"]', insp); if (f) f.focus({ preventScroll: true });
}
function saveRule() {
  const d = S.draft;
  if (!d || !d.tokens.length) return;
  const id = 'r' + (Date.now() % 100000), keys = S.txs.filter(t => qOf(t) === 'review' && matches(d, t)).map(t => t.k);
  snap('New rule for ' + d.tokens.join(' + '));
  S.rules.push({ id, tokens: d.tokens.slice(), dir: d.dir, cat: d.cat, name: d.name.trim(), on: true });
  const nxt = nextAfter(keys);
  keys.forEach(k => { const t = byK(k); t.cat = d.cat; t.rule = id; if (d.name.trim()) t.name = d.name.trim(); });
  S.draft = null; S.rsel = id;
