function runRule(r) {
  const keys = S.txs.filter(t => qOf(t) === 'review' && matches(r, t)).map(t => t.k);
  if (!keys.length) return;
  snap('Ran rule ' + r.tokens.join(' + '));
  keys.forEach(k => { const t = byK(k); t.cat = r.cat; t.rule = r.id; if (r.name) t.name = r.name; });
  render(true);
  toast(keys.length + ' sorted as ' + esc(CAT[r.cat].n), undo);
