  b.classList.add('is-busy'); b.disabled = true; $('span', b).textContent = 'Syncing…';
  setTimeout(() => {
    if (!root.isConnected) return;
    snap('Sync from Brackwater');
    let auto = 0;
    POOL.forEach(p => {
      const t = JSON.parse(JSON.stringify(p)), r = S.rules.find(x => x.on && matches(x, t));
