/* ── menu (row category or bulk) ── */
function openMenu(anchor, keys) {
  S.menu = keys;
  menu.innerHTML = CATS.map((c, i) => `<button type="button" role="menuitem" data-act="mpick" data-c="${c.k}" style="--h:${c.h}" tabindex="-1"><kbd>${i + 1}</kbd>${esc(c.n)}</button>`).join('');
  menu.hidden = false;
  const rr = root.getBoundingClientRect(), b = anchor.getBoundingClientRect(), mw = menu.offsetWidth, mh = menu.offsetHeight;
  let x = Math.min(rr.width - mw - 10, Math.max(10, b.right - rr.left - mw)), y = b.bottom - rr.top + 6;
  if (y + mh > rr.height - 10) y = Math.max(10, b.top - rr.top - mh - 6);
  menu.style.left = x + 'px'; menu.style.top = y + 'px';
  menu.querySelector('[role="menuitem"]').focus({ preventScroll: true });
}
function closeMenu(refocus) {
  if (menu.hidden) return;
  menu.hidden = true; menu.innerHTML = ''; S.menu = null;
  if (refocus) focusCur();
}

/* ── events ── */
root.addEventListener('click', e => {
  const b = e.target.closest('[data-act], [data-q]');
  if (!menu.hidden && !e.target.closest('[data-menu]')) closeMenu(false);
  if (!b || !root.contains(b)) return;
  if (b.dataset.q && !b.dataset.act) {
    S.q = b.dataset.q; S.draft = null; S.sel.clear(); S.view = 'list'; root.dataset.view = 'list';
    $('[data-scroll]').scrollTop = 0; render(true); return;
  }
  const row = b.closest(`.${ID}-row, .${ID}-rule`), k = row && row.dataset.k;
  switch (b.dataset.act) {
    case 'cur': setCur(k, true); break;
    case 'accept': categorise([k], byK(k).sug); break;
    case 'rowmenu': S.cur = k; openMenu(b, [k]); break;
    case 'bulkmenu': openMenu(b, [...S.sel]); break;
    case 'mpick': { const keys = S.menu || []; closeMenu(false); categorise(keys, b.dataset.c); break; }
    case 'bulkaccept': { const keys = [...S.sel].filter(x => qOf(byK(x)) === 'review'); if (!keys.length) break; const nxt = nextAfter(keys); snap('Accepted ' + keys.length + ' suggestions'); keys.forEach(x => { byK(x).cat = byK(x).sug; S.sel.delete(x); }); leaveThen(keys, () => { if (nxt) S.cur = nxt; render(true); }); toast(esc(hist[hist.length - 1].label), undo); break; }
    case 'bulkex': setExcluded([...S.sel], true); break;
    case 'bulkin': setExcluded([...S.sel], false); break;
    case 'bulkclear': S.sel.clear(); render(false); break;
    case 'unreview': unreview(k || S.cur); break;
    case 'include': setExcluded([k || S.cur], false); break;
    case 'exclude': setExcluded([S.cur], true); break;
    case 'pick': categorise([S.cur], b.dataset.c); break;
    case 'rnew': newDraft(); break;
    case 'tok': { const w = b.dataset.w, d = S.draft; d.tokens = d.tokens.includes(w) ? d.tokens.filter(x => x !== w) : tokens(byK(d.from).raw).filter(x => x === w || d.tokens.includes(x)); d.name = title(d.tokens.filter(isWord).join(' ')) || d.name; renderRows(false); renderInsp(); const f = $(`[data-act="tok"][data-w="${CSS.escape(w)}"]`, insp); if (f) f.focus({ preventScroll: true }); break; }
    case 'dir': S.draft.dir = b.dataset.v; renderRows(false); renderInsp(); $(`[data-act="dir"][data-v="${b.dataset.v}"]`, insp).focus({ preventScroll: true }); break;
    case 'rsave': saveRule(); break;
    case 'rcancel': S.draft = null; renderRows(false); renderInsp(); focusCur(); break;
    case 'rsel': S.rsel = k; renderRows(false); renderInsp(); S.view = 'insp'; root.dataset.view = 'insp'; break;
    case 'rtoggle': { const r = S.rules.find(x => x.id === k); snap((r.on ? 'Paused' : 'Resumed') + ' rule ' + r.tokens.join(' + ')); r.on = !r.on; S.rsel = k; render(false); toast(r.on ? 'Rule active · runs on every sync' : 'Rule paused · new transactions skip it', undo); break; }
