    case 'rdel': { const r = S.rules.find(x => x.id === S.rsel); if (!r) break; snap('Deleted rule ' + r.tokens.join(' + ')); S.rules = S.rules.filter(x => x !== r); S.rsel = S.rules[0] && S.rules[0].id; render(true); toast('Rule deleted · ' + hits(r) + ' sorted transactions keep their category', undo); break; }
    case 'sync': sync(); break;
    case 'undo': undo(); break;
    case 'back': S.view = 'list'; root.dataset.view = 'list'; renderInsp(); focusCur(); break;
    case 'clearsearch': S.search = ''; $('[data-search]').value = ''; render(false); break;
  }
});
root.addEventListener('change', e => {
  const t = e.target;
  if (t.matches('[data-check]')) {
    const k = t.closest(`.${ID}-row`).dataset.k;
    t.checked ? S.sel.add(k) : S.sel.delete(k);
    t.closest(`.${ID}-row`).setAttribute('aria-selected', t.checked);
    renderChrome();
  } else if (t.matches('[data-rcat]')) { S.draft.cat = t.value; }
  else if (t.matches('[data-name]')) {
    const tx = byK(S.cur), v = t.value.trim();
    if (tx && v && v !== nameOf(tx)) { snap('Renamed to ' + v); tx.name = v; renderRows(false); toast('Payee renamed to “' + esc(v) + '”', undo); }
  }
});
root.addEventListener('input', e => {
  if (e.target.matches('[data-search]')) { S.search = e.target.value.trim(); renderRows(false); renderChrome(); }
  if (e.target.matches('[data-rname]')) S.draft.name = e.target.value;
});

root.addEventListener('keydown', e => {
  const t = e.target, k = e.key, typing = t.matches('input:not([type=checkbox]), select, textarea');
  if (!menu.hidden && t.closest('[data-menu]')) {
    const items = $$('[role="menuitem"]', menu), i = items.indexOf(t);
    if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); items[(i + (k === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus(); }
    else if (k === 'Escape') { e.preventDefault(); closeMenu(true); }
    else if (/^[1-9]$/.test(k)) { e.preventDefault(); items[+k - 1].click(); }
    else if (k === 'Tab') closeMenu(false);
    return;
  }
  if ((e.metaKey || e.ctrlKey) && k.toLowerCase() === 'z' && !e.shiftKey && !typing) { e.preventDefault(); undo(); return; }
  if (k === 'Escape') {
    if (typing && t.matches('[data-search]') && t.value) { t.value = ''; S.search = ''; render(false); return; }
    if (S.draft) { S.draft = null; renderRows(false); renderInsp(); focusCur(); return; }
    if (S.sel.size) { S.sel.clear(); render(false); return; }
    if (S.view === 'insp') { S.view = 'list'; root.dataset.view = 'list'; focusCur(); }
    return;
  }
  if (t.closest('[role="listbox"]') && (k === 'ArrowDown' || k === 'ArrowUp')) {
    e.preventDefault();
    const o = $$('[role="option"]', insp), i = o.indexOf(t.closest('[role="option"]'));
    const n = o[(i + (k === 'ArrowDown' ? 1 : -1) + o.length) % o.length];
    o.forEach(x => { x.tabIndex = x === n ? 0 : -1; }); n.focus(); return;
  }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const inList = !!t.closest(`.${ID}-list`) || t === root;
  if (k === '/') { e.preventDefault(); $('[data-search]').focus(); return; }
  if (S.q === 'rules') {
    if ((k === 'ArrowDown' || k === 'ArrowUp' || k === 'j' || k === 'k') && inList) {
      e.preventDefault();
      const ids = S.rules.map(r => r.id), i = ids.indexOf(S.rsel), n = ids[Math.max(0, Math.min(ids.length - 1, i + (k === 'ArrowDown' || k === 'j' ? 1 : -1)))];
      if (n) { S.rsel = n; renderRows(false); renderInsp(); $(`.${ID}-rule[data-cur] .${ID}-main`).focus({ preventScroll: true }); }
    }
    return;
  }
  const list = shown().map(x => x.k), i = list.indexOf(S.cur);
  if ((k === 'ArrowDown' || k === 'ArrowUp' || k === 'j' || k === 'k') && (inList || t.closest(`.${ID}-insp`) === null)) {
    e.preventDefault();
    const n = list[Math.max(0, Math.min(list.length - 1, i + (k === 'ArrowDown' || k === 'j' ? 1 : -1)))];
    if (n) { setCur(n); focusCur(); }
  } else if (/^[1-9]$/.test(k) && S.cur && !S.draft) {
    e.preventDefault();
    const keys = S.sel.size ? [...S.sel] : [S.cur];
    categorise(keys, CATS[+k - 1].k);
  } else if ((k === 'x' || k === 'X') && S.cur) {
    e.preventDefault();
