  --apb-bills-line: color-mix(in oklch, var(--apb-bills-ink) 11%, transparent);
  --apb-bills-line2: color-mix(in oklch, var(--apb-bills-ink) 20%, transparent);
  --apb-bills-mute: color-mix(in oklch, var(--apb-bills-ink) 58%, var(--apb-bills-bg));
  --apb-bills-faint: color-mix(in oklch, var(--apb-bills-ink) 36%, var(--apb-bills-bg));
