/* ── Bill pay with a projected checking balance. One series() feeds the chart, the stats and the warnings ── */
const ID = 'apb-bills';
const fmt = c => (c < 0 ? '−' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmt0 = c => (c < 0 ? '−' : '') + '$' + Math.round(Math.abs(c) / 100).toLocaleString('en-US');
const TODAY = 8, START = 362444, SAV0 = 624000, LATE = 2500;
const DOW = d => ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][(d + 3) % 7];   /* Oct 1 2026 is a Thursday */
const day = d => DOW(d) + ', Oct ' + d;
const rel = d => d === TODAY ? 'today' : d === TODAY + 1 ? 'tomorrow' : d > TODAY ? 'in ' + (d - TODAY) + ' days' : (TODAY - d) + ' days ago';
const PAYS = [{ d: 15, amt: 231540 }, { d: 30, amt: 231540 }];
const isPay = d => PAYS.some(p => p.d === d);
const S = {
  sel: 'car', tab: 'due', buffer: 50000, view: 'list',
  bills: [
    { k: 'rent', n: 'Rent', p: 'Alder Court Apartments', ic: 'AC', h: 200, amt: 164000, due: 1, on: 1, paid: 1, auto: true, from: 'chk', conf: 'AC-20481', hist: [164000, 164000, 164000] },
    { k: 'phone', n: 'Phone', p: 'Relay Mobile', ic: 'RM', h: 255, amt: 7200, due: 5, on: 5, paid: 5, auto: true, from: 'chk', conf: 'RM-77341', hist: [7200, 7200, 6890] },
    { k: 'card', n: 'Credit card', p: 'Juniper Card ··3307', ic: 'JC', h: 25, amt: 118640, stmt: 118640, min: 3500, due: 18, on: 9, auto: false, from: 'chk', vary: true, hist: [94215, 132070, 87730] },
    { k: 'power', n: 'Electric', p: 'Northgrid Power', ic: 'NG', h: 85, amt: 9622, due: 12, on: 12, auto: true, from: 'chk', hist: [8840, 11210, 10467] },
    { k: 'car', n: 'Car loan', p: 'Lakeline Credit Union', ic: 'LC', h: 150, amt: 31248, due: 20, on: 13, auto: false, from: 'chk', hist: [31248, 31248, 31248] },
    { k: 'net', n: 'Internet', p: 'Cobalt Fiber', ic: 'CF', h: 230, amt: 5999, due: 14, on: 14, auto: true, from: 'chk', hist: [5999, 5999, 5999] },
    { k: 'water', n: 'Water & sewer', p: 'Bellmere Utilities', ic: 'BU', h: 210, amt: 4180, due: 22, on: 22, auto: false, from: 'chk', hist: [3925, 4410, 4062] },
    { k: 'gym', n: 'Climbing gym', p: 'Basalt Climbing Co.', ic: 'BC', h: 45, amt: 6200, due: 25, on: 25, auto: true, from: 'chk', hist: [6200, 6200, 6200] },
    { k: 'tv', n: 'Streaming', p: 'Reelhouse', ic: 'RH', h: 330, amt: 1599, due: 27, on: 27, auto: true, from: 'chk', hist: [1599, 1599, 1599] },
    { k: 'ins', n: 'Renters insurance', p: 'Harbor Mutual', ic: 'HM', h: 120, amt: 1850, due: 28, on: 28, auto: false, from: 'chk', hist: [1850, 1850, 1850] },
    { k: 'loan', n: 'Student loan', p: 'Fairpath Servicing', ic: 'FS', h: 280, amt: 24410, due: 31, on: 30, auto: false, from: 'chk', hist: [24410, 24410, 24410] }
  ]
};
const byK = k => S.bills.find(b => b.k === k);
const when = b => b.paid || b.on;

/* end-of-day checking balance for every day of October */
function series(bills) {
  const bal = new Array(32).fill(0);
  let v = START;
  for (let d = 1; d <= 31; d++) {
    PAYS.forEach(p => { if (p.d === d) v += p.amt; });
    (bills || S.bills).forEach(b => { if (when(b) === d && b.from === 'chk') v -= b.amt; });
