  let best = null;
  S.bills.filter(b => !b.paid && !b.auto && b.from === 'chk' && b.on <= w[0].b).forEach(b => {
    PAYS.filter(p => p.d > b.on && p.d <= b.due).forEach(p => {
      const trial = S.bills.map(x => x === b ? { ...x, on: p.d } : x), low = lowOf(series(trial)).v;
      if (!best || low > best.low) best = { b, d: p.d, low };
