  });
  return best && best.low > lowOf(bal).v ? best : null;
}

/* ── history ── */
const hist = [];
const snap = label => hist.push({ label, d: JSON.stringify({ bills: S.bills, buffer: S.buffer }) });
function undo() {
  const h = hist.pop();
  if (!h) return;
  const d = JSON.parse(h.d); S.bills = d.bills; S.buffer = d.buffer;
  render();
  toast('Undid: ' + esc(h.label));
}
function commit(label, fn, quiet) { snap(label); fn(); render(); if (!quiet) toast(esc(label), undo); }

/* ── chart ── */
const chart = $('[data-chart]'), svg = $('[data-svg]'), lane = $('[data-lane]'), tip = $('[data-tip]');
const uid = ID + '-' + Math.random().toString(36).slice(2, 8);
const CSSD = typeof CSS !== 'undefined' && CSS.supports && CSS.supports('d', 'path("M0 0")');
let G = null;
function geom() {
  const W = Math.max(280, chart.clientWidth), H = Math.max(160, chart.clientHeight);
  const padL = W < 520 ? 38 : 50, padR = 14, top = 16, laneH = 58, plotB = H - laneH - 20;
  const slot = (W - padL - padR) / 31;
