  for (let d = 1; d <= 31; d++) {
    const show = d === 1 || d === TODAY || d % 5 === 0 || d === 31 || (slot > 26);
    if (show && !(slot <= 26 && (d === TODAY - 1 || d === TODAY + 1 || (d === 30 && slot < 16)))) days += `<text x="${cx(d)}" y="${plotB + 13}" class="${ID}-dx${d === TODAY ? ' is-today' : ''}${isPay(d) ? ' is-pay' : ''}">${d}</text>`;
  }
  svg.innerHTML = `<defs>
      <clipPath id="${uid}-past"><rect x="0" y="0" width="${cx(TODAY) + slot / 2}" height="${H}"/></clipPath>
      <clipPath id="${uid}-futr"><rect x="${cx(TODAY) + slot / 2}" y="0" width="${W}" height="${H}"/></clipPath>
      <clipPath id="${uid}-low"><rect data-lowclip x="0" y="0" width="${W}" height="${H}"/></clipPath>
      <linearGradient id="${uid}-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" class="${ID}-g0"/><stop offset="1" class="${ID}-g1"/></linearGradient>
    </defs>
    <g data-grid></g>
    <rect class="${ID}-past" x="${padL}" y="${top}" width="${cx(TODAY) + slot / 2 - padL}" height="${plotB - top}"/>
    <path class="${ID}-area" data-p="area" fill="url(#${uid}-fill)"/>
    <path class="${ID}-danger" data-p="danger" clip-path="url(#${uid}-low)"/>
    <line class="${ID}-bufl" data-bufl x1="${padL}" x2="${W - padR}"/>
    <text class="${ID}-bufl-t" data-buft x="${W - padR}" text-anchor="end"></text>
    <path class="${ID}-line" data-p="line" clip-path="url(#${uid}-past)"/>
    <path class="${ID}-line is-proj" data-p="proj" clip-path="url(#${uid}-futr)"/>
    <line class="${ID}-today" x1="${cx(TODAY) + slot / 2}" x2="${cx(TODAY) + slot / 2}" y1="${top - 6}" y2="${plotB}"/>
    <text class="${ID}-today-t" x="${cx(TODAY) + slot / 2 + 5}" y="${top + 4}">Today</text>
    <line class="${ID}-guide" data-guide y1="${top}" y2="${plotB}" x1="-10" x2="-10"/>
    ${days}`;
  update(false);
}
let yMaxShown = 0;
function update(animate) {
  if (!G) return;
