  for (let i = 1; i <= 31; i++) { d += ` L${cx(i).toFixed(1)} ${Y(prev).toFixed(1)} L${cx(i).toFixed(1)} ${Y(bal[i]).toFixed(1)}`; prev = bal[i]; }
  d += ` L${(padL + 31 * slot).toFixed(1)} ${Y(prev).toFixed(1)}`;
  const area = d + ` L${(padL + 31 * slot).toFixed(1)} ${plotB} L${padL} ${plotB} Z`;
  const set = (k, v) => { const p = $(`[data-p="${k}"]`, svg); p.setAttribute('d', v); if (CSSD) p.style.d = `path("${v}")`; };
  chart.classList.toggle('is-still', !animate);
  const above = d + ` L${(padL + 31 * slot).toFixed(1)} ${top} L${padL} ${top} Z`;
  set('line', d); set('proj', d); set('area', area); set('danger', above);
