  const bl = $('[data-bufl]', svg); bl.setAttribute('y1', by); bl.setAttribute('y2', by);
  const bt = $('[data-buft]', svg); bt.setAttribute('y', by - 5); bt.textContent = fmt0(S.buffer) + ' buffer';
  drawLane();
}
function drawLane() {
