@keyframes apb-invoice-stamp { 0% { opacity: 0; transform: rotate(-14deg) scale(2.2); filter: blur(4px); } 60% { opacity: 1; transform: rotate(-14deg) scale(.94); filter: none; } 100% { opacity: 1; transform: rotate(-14deg) scale(1); } }
