  --apb-invoice-tint: color-mix(in oklch, var(--apb-invoice-accent) 9%, var(--apb-invoice-bg));
  --apb-invoice-shade: color-mix(in oklch, var(--apb-invoice-ink) 40%, transparent);
  --apb-invoice-ease: cubic-bezier(.2, .8, .2, 1);
