/* ── actions ── */
function selectInv(no, open) {
  S.sel = no; S.grab = null;
  render();
  if (open) { S.view = 'work'; root.dataset.view = 'work'; }
}
function addLine() {
  const i = cur();
  if (i.st !== 'draft') return;
  snap('Added a line');
  const l = L('', 1, 'ea', 0, 20); i.lines.push(l);
  flip(() => $$(`.${ID}-line`), () => renderEditor());
  paintTotals();
  const d = $(`[data-k="${l.k}"] [data-l="d"]`); if (d) { d.focus(); d.scrollIntoView({ block: 'nearest' }); }
}
function moveLine(k, dir) {
  const i = cur(), n = i.lines.findIndex(l => l.k === k), m = n + dir;
  if (i.st !== 'draft' || n < 0 || m < 0 || m >= i.lines.length) return false;
  snap('Moved a line');
  const [l] = i.lines.splice(n, 1); i.lines.splice(m, 0, l);
  flip(() => $$(`.${ID}-line`), () => renderEditor());
  renderPreview();
  return true;
}
function pdf(b) {
  if (b.classList.contains('is-busy')) return;
  b.classList.add('is-busy');
  setTimeout(() => { if (!root.isConnected) return; b.classList.remove('is-busy'); toast(cur().no + '.pdf generated · 1 page, A4'); }, RM.matches ? 80 : 950);
}
function newInv(from) {
  snap(from ? 'Duplicated ' + from.no : 'New invoice');
  const nums = S.inv.map(x => +x.no.slice(4)), no = 'INV-' + String(Math.max(...nums) + 1).padStart(4, '0');
  const lines = from ? from.lines.map(l => L(l.d, l.q, l.u, l.r / 100, l.v)) : [L('', 1, 'ea', 0, 20)];
  S.inv.unshift({ no, st: 'draft', c: from ? from.c : 'ostr', issued: iso(TODAY), terms: from ? from.terms : 30, disc: from ? from.disc : 0, paid: 0, notes: from ? from.notes : '', log: [['8 Oct', from ? 'Duplicated from ' + from.no : 'Draft created']], lines });
  S.filter = S.filter === 'paid' || S.filter === 'unpaid' ? 'all' : S.filter;
  S.mode = 'edit';
  selectInv(no, true);
  toast((from ? 'Duplicated as ' : 'Started ') + no, undo);
  const d = $(`[data-editor] [data-l="d"]`); if (d && !from) d.focus();
}
/* payment dialog */
const modal = $('[data-modal]'), scrim = $('[data-scrim]');
function openPay() {
  const i = cur(), t = totals(i);
  modal.innerHTML = `<form data-payform novalidate><h3>Record a payment</h3><p>${esc(CLIENTS[i.c].n)} · ${i.no} · balance ${gbp(t.bal)}</p>
    <label class="${ID}-f"><span>Amount received</span><span class="${ID}-money"><small>£</small><input data-pamt value="${(t.bal / 100).toFixed(2)}" inputmode="decimal"></span></label>
    <div class="${ID}-f"><span>Method</span><div class="${ID}-seg" role="radiogroup" aria-label="Method">${['Bank transfer', 'Card', 'Cash'].map((m, n) => `<button type="button" role="radio" data-pm="${m}" aria-checked="${n === 0}">${m}</button>`).join('')}</div></div>
    <p class="${ID}-err" data-perr role="alert"></p>
    <div class="${ID}-mrow"><button type="button" class="${ID}-btn" data-act="mclose">Cancel</button><button type="submit" class="${ID}-btn is-accent">Record ${I.coin}</button></div></form>`;
  modal.hidden = false; scrim.hidden = false;
  const a = $('[data-pamt]', modal); a.focus(); a.select();
}
function closeModal() { if (modal.hidden) return; modal.hidden = true; scrim.hidden = true; modal.innerHTML = ''; const b = $('[data-act="pay"]'); if (b) b.focus({ preventScroll: true }); }
function submitPay() {
  const i = cur(), t = totals(i), v = Math.round(parseFloat(($('[data-pamt]', modal).value || '').replace(/[£,\s]/g, '')) * 100), m = $('[aria-checked="true"]', modal).dataset.pm;
  const err = $('[data-perr]', modal);
  if (!(v > 0)) { err.textContent = 'Enter the amount you received.'; return; }
  if (v > t.bal) { err.textContent = 'That’s more than the ' + gbp(t.bal) + ' balance.'; return; }
  closeModal();
  snap('Recorded ' + gbp(v));
  i.paid += v; i.st = i.paid >= t.total ? 'paid' : 'part';
  i.log.push(['8 Oct', (i.st === 'paid' ? 'Paid ' : 'Part payment ') + gbp(v) + ' by ' + m.toLowerCase()]);
  render();
  const st = $(`.${ID}-stamp`); if (st) st.classList.add('is-new');
  toast(i.st === 'paid' ? i.no + ' is paid in full' : gbp(v) + ' recorded · ' + gbp(totals(i).bal) + ' still due', undo);
}

/* ── events ── */
let pre = null;
root.addEventListener('focusin', e => { if (e.target.matches('[data-l], [data-f]') && !e.target.disabled) pre = JSON.stringify(S.inv); });
root.addEventListener('input', e => {
  const t = e.target, i = cur();
  if (i.st !== 'draft') return;
  if (t.dataset.l) {
    const l = i.lines.find(x => x.k === t.closest('[data-k]').dataset.k);
    if (t.dataset.l === 'd') l.d = t.value;
    if (t.dataset.l === 'q') l.q = t.value.replace(/[^\d.]/g, '');
    if (t.dataset.l === 'r') l.r = Math.round((parseFloat(t.value.replace(/[£,\s]/g, '')) || 0) * 100);
    if (t.dataset.l === 'v') l.v = +t.value;
    paintTotals();
  } else if (t.dataset.f === 'disc') { i.disc = Math.min(100, Math.max(0, parseFloat(t.value) || 0)); paintTotals(); }
  else if (t.dataset.f === 'notes') { i.notes = t.value; renderPreview(); }
});
root.addEventListener('change', e => {
  const t = e.target, i = cur();
  if (i.st !== 'draft' || !t.matches('[data-l], [data-f]')) return;
  if (t.dataset.f === 'c' || t.dataset.f === 'terms' || t.dataset.f === 'issued') {
    if (t.dataset.f === 'c') i.c = t.value;
    if (t.dataset.f === 'terms') i.terms = +t.value;
    if (t.dataset.f === 'issued' && t.value) i.issued = t.value;
    renderEditor(); paintTotals();
  }
  if (t.dataset.l === 'r') t.value = (cur().lines.find(x => x.k === t.closest('[data-k]').dataset.k).r / 100).toFixed(2);
  if (pre && pre !== JSON.stringify(S.inv)) { hist.push({ label: 'Edited ' + i.no, d: pre, sel: S.sel }); pre = JSON.stringify(S.inv); renderBar(); }
