@keyframes apb-receipts-beam { 0% { transform: translateY(-10%); opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { transform: translateY(1000%); opacity: 0; } }
@keyframes apb-receipts-box { from { opacity: 0; transform: scale(1.12); } to { opacity: 1; transform: none; } }
@keyframes apb-receipts-shimmer { to { --apb-receipts-sx: 200%; } }
@keyframes apb-receipts-develop { from { filter: blur(3px) brightness(.7) contrast(.8); } to { filter: none; } }
@keyframes apb-receipts-pulse { 0% { transform: scale(1); } 40% { transform: scale(.94); } 100% { transform: scale(1); } }
@keyframes apb-receipts-rise { from { opacity: 0; transform: translateY(6px); } }
@property --apb-receipts-sx { syntax: "<percentage>"; inherits: false; initial-value: -100%; }

.apb-receipts {
  --apb-receipts-bg: oklch(0.21 0.012 55);
  --apb-receipts-ink: oklch(0.95 0.012 80);
  --apb-receipts-accent: oklch(0.8 0.15 70);
  --apb-receipts-bad: oklch(0.7 0.17 32);
  --apb-receipts-good: oklch(0.8 0.12 150);
