  --apb-receipts-raise: color-mix(in oklch, var(--apb-receipts-ink) 5%, var(--apb-receipts-bg));
  --apb-receipts-raise2: color-mix(in oklch, var(--apb-receipts-ink) 10%, var(--apb-receipts-bg));
  --apb-receipts-line: color-mix(in oklch, var(--apb-receipts-ink) 10%, transparent);
