  --apb-receipts-faint: color-mix(in oklch, var(--apb-receipts-ink) 36%, var(--apb-receipts-bg));
  --apb-receipts-paper: oklch(0.96 0.014 90);
  --apb-receipts-ease: cubic-bezier(.2, .8, .2, 1);
  --apb-receipts-spring: linear(0, .08 4%, .31 9%, .62 15%, .87 21%, 1.02 27%, 1.07 33%, 1.05 39%, 1.01 48%, .995 60%, 1);
  --apb-receipts-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; box-sizing: border-box; width: 100%; height: var(--apb-receipts-h, 680px);
  container-type: inline-size; container-name: apb-receipts;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apb-receipts-line);
  background: var(--apb-receipts-bg); color: var(--apb-receipts-ink);
  font: 13.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--apb-receipts-accent);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
