  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; opacity: .42; }
  & svg { display: block; width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apb-receipts-accent); outline-offset: 2px; border-radius: 7px; }
  & kbd { font: 600 10.5px/1 var(--apb-receipts-mono); padding: 3px 5px; border-radius: 4px; background: var(--apb-receipts-raise2); color: var(--apb-receipts-mute); }

  & .apb-receipts-app { display: grid; height: 100%; grid-template-columns: 300px minmax(0, 1fr) 330px; grid-template-rows: minmax(0, 1fr); grid-template-areas: "report stage form"; }

  /* ── report ── */
  & .apb-receipts-report { grid-area: report; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-height: 0; border-right: 1px solid var(--apb-receipts-line); background: var(--apb-receipts-deep); }
  & .apb-receipts-rhead { padding: 16px 16px 12px;
    & h2 { margin: 10px 0 2px; font-size: 18px; font-weight: 720; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; }
    & p { margin: 0; font-size: 12px; color: var(--apb-receipts-mute); text-wrap: pretty; }
  }
