  }
  & .apb-receipts-chip { margin-left: auto; font-style: normal; height: 20px; padding: 0 8px; display: inline-flex; align-items: center; border-radius: 99px; font-size: 11px; font-weight: 700;
    &.is-draft { background: var(--apb-receipts-raise2); color: var(--apb-receipts-mute); }
