    & div:nth-child(2) dd { color: var(--apb-receipts-accent); }
  }
  & .apb-receipts-lines { overflow: auto; overscroll-behavior: contain; padding: 4px 8px 10px; scrollbar-width: thin; }
  & .apb-receipts-line { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; width: 100%; padding: 9px 8px; border-radius: 11px; text-align: left; transition: background-color .15s; animation: apb-receipts-rise .35s var(--apb-receipts-ease) both; animation-delay: calc(var(--i) * 35ms);
    &:hover { background: var(--apb-receipts-raise); }
    &[aria-selected="true"] { background: var(--apb-receipts-raise2); box-shadow: inset 2px 0 0 var(--apb-receipts-accent); }
  }
  & .apb-receipts-cat { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: color-mix(in oklch, var(--c, var(--apb-receipts-accent)) 16%, transparent); color: var(--c, var(--apb-receipts-accent));
    &.is-meals { --c: oklch(0.8 0.13 50); } &.is-lodging { --c: oklch(0.78 0.1 250); } &.is-fuel { --c: oklch(0.8 0.13 95); } &.is-ground { --c: oklch(0.78 0.11 180); } &.is-supplies { --c: oklch(0.78 0.12 140); } &.is-other { --c: oklch(0.75 0.03 80); }
  }
  & .apb-receipts-lt, & .apb-receipts-la { display: grid; min-width: 0; }
