  & .apb-receipts-lt small { font-size: 11.5px; color: var(--apb-receipts-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apb-receipts-la { justify-items: end; & b { font-weight: 660; font-variant-numeric: tabular-nums; } & small { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--apb-receipts-faint); white-space: nowrap; } & small.is-miss { color: var(--apb-receipts-mute); } }
  & .apb-receipts-line.has-flag .apb-receipts-la small { color: var(--apb-receipts-bad); }
  & .apb-receipts-dot { display: grid; place-items: center; width: 15px; height: 15px; border-radius: 50%; background: var(--apb-receipts-bad); color: var(--apb-receipts-bg); font: 800 9.5px/1 system-ui; font-style: normal; }
  & .apb-receipts-rfoot { display: grid; gap: 8px; padding: 12px 14px 14px; border-top: 1px solid var(--apb-receipts-line);
    & p { margin: 0; font-size: 12.5px; } & p.is-bad { color: var(--apb-receipts-bad); } & p.is-ok { color: var(--apb-receipts-good); }
  }
  & .apb-receipts-flow { list-style: none; margin: 0; padding: 0 0 0 4px; display: grid; gap: 7px; font-size: 12.5px; color: var(--apb-receipts-faint);
    & li { display: flex; align-items: center; gap: 9px; } & li::before { content: ""; width: 9px; height: 9px; border-radius: 50%; border: 2px solid var(--apb-receipts-line2); }
    & .is-done { color: var(--apb-receipts-ink); } & .is-done::before { background: var(--apb-receipts-good); border-color: var(--apb-receipts-good); }
    & .is-now { color: var(--apb-receipts-accent); } & .is-now::before { border-color: var(--apb-receipts-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apb-receipts-accent) 25%, transparent); }
  }
  & .apb-receipts-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 36px; padding: 0 14px; border-radius: 10px; font-size: 13px; font-weight: 650; white-space: nowrap; background: var(--apb-receipts-raise2); transition: transform .15s var(--apb-receipts-ease), background-color .15s, filter .15s;
    &:hover:not(:disabled):not([aria-disabled="true"]) { background: color-mix(in oklch, var(--apb-receipts-ink) 15%, var(--apb-receipts-bg)); }
