    position: relative; width: 248px; padding: 18px 18px 22px; background: linear-gradient(180deg, transparent 70%, oklch(0.9 0.02 80 / .6)), repeating-linear-gradient(0deg, transparent 0 3px, oklch(0.5 0.02 80 / .03) 3px 4px), var(--apb-receipts-paper); color: oklch(0.28 0.01 70); font: 500 11.5px/1.5 var(--apb-receipts-mono); letter-spacing: -.01em; transform: rotate(var(--tilt)); -webkit-mask: var(--zig); mask: var(--zig); filter: drop-shadow(0 20px 26px rgb(0 0 0 / .45));
    animation: apb-receipts-develop .7s var(--apb-receipts-ease);
