/* ── report ── */
const locked = () => S.status !== 'draft';
function renderReport(animate) {
  const tot = S.exp.reduce((s, e) => s + e.amt, 0), mine = S.exp.filter(e => e.pay === 'personal').reduce((s, e) => s + e.amt, 0);
  $('[data-rhead]').innerHTML = `<div class="${ID}-brand"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3.5h12v17l-3-2-3 2-3-2-3 2z"/><path d="M9 8.5h6M9 12h6"/></svg><span>Fieldbook · Corvid Survey Co.</span><em class="${ID}-chip is-${S.status}">${S.status === 'draft' ? 'Draft' : 'Submitted'}</em></div>
    <h2>Bellmere Wind Farm site visit</h2><p>Oct 5–8, 2026 · Ana Lindqvist · billable to Halden Energy</p>
