      <span class="${ID}-la"><b>${usd(e.amt)}</b><small class="${e.r ? 'is-ok' : 'is-miss'}">${f.length ? `<i class="${ID}-dot">${f.length}</i>${f.length === 1 ? '1 issue' : f.length + ' issues'}` : e.r ? 'Receipt ✓' : 'No receipt'}</small></span></button>`;
  }).join('');
