    : `<ol class="${ID}-flow"><li class="is-done">Submitted · Oct 8, 4:12 PM</li><li class="is-now">Rafael Okafor reviewing</li><li>Finance check</li><li>Reimbursed to ··0918</li></ol><button type="button" class="${ID}-btn" data-act="recall">Recall to edit</button>`;
}

/* ── the receipt on the stage ── */
const stage = $('[data-stage]');
function docHtml(doc) {
  const rows = doc.items.map(([n, c]) => `<div><span>${esc(n)}</span><span>${usd(c)}</span></div>`).join('');
  return `<article class="${ID}-paper" style="--tilt:${(doc.d % 2 ? -1.6 : 1.2)}deg">
    <header data-box="m"><b>${esc(doc.m)}</b>${doc.addr.map(a => `<span>${esc(a)}</span>`).join('')}</header>
    <p data-box="d">10/0${doc.d}/2026 &nbsp; ${doc.t}</p>
    <div class="${ID}-items">${rows}</div>
