  else { const e = byK(sel.k); doc = e && e.r ? DOCS[e.r] : null; }
  $('[data-stitle]').textContent = sel.t === 'scan' ? (scanning ? 'Reading ' + DOCS[sel.k].img + '…' : 'Scanned ' + DOCS[sel.k].img) : doc ? 'Receipt · ' + doc.img : 'No receipt yet';
