  form.innerHTML = `<div class="${ID}-fhead"><small>${CATS[e.cat]} · ${day(e.d)}</small><h3>${esc(e.m)}</h3></div>
    ${f.length ? `<ul class="${ID}-flags">${f.map(x => `<li>${esc(x.t)}</li>`).join('')}</ul>` : ''}
    ${formBody(e, conf, dis)}
    <div class="${ID}-acts"><button type="button" class="${ID}-btn is-danger" data-act="remove" ${lock ? 'disabled title="Submitted reports are locked"' : ''}>Remove <kbd>Del</kbd></button></div>`;
}
function formBody(x, conf, dis) {
  return `<div class="${ID}-grid">
      ${fieldRow('m', 'Merchant', `<input data-in="m" value="${esc(x.m)}" ${dis}>`, conf && conf.m)}
      ${fieldRow('d', 'Date', `<select data-in="d" ${dis}>${[5, 6, 7, 8].map(d => `<option value="${d}" ${x.d === d ? 'selected' : ''}>${day(d)}</option>`).join('')}</select>`, conf && conf.d)}
      ${fieldRow('t', 'Amount', `<input data-in="amt" value="${(x.amt / 100).toFixed(2)}" inputmode="decimal" ${dis}>`, conf && conf.t)}
      ${fieldRow('x', 'Tax', `<input data-in="tax" value="${(x.tax / 100).toFixed(2)}" inputmode="decimal" ${dis}>`, conf && conf.x)}
    </div>
    <div class="${ID}-sec"><span class="${ID}-lab">Category</span><div class="${ID}-cats" role="radiogroup" aria-label="Category">${Object.entries(CATS).map(([k, n]) => `<button type="button" role="radio" data-act="cat" data-v="${k}" aria-checked="${x.cat === k}" ${dis} class="is-${k}">${ic(k)}${n}</button>`).join('')}</div></div>
    <div class="${ID}-sec ${ID}-row2">
      <div><span class="${ID}-lab">Paid with</span><div class="${ID}-seg" role="radiogroup" aria-label="Paid with"><button type="button" role="radio" data-act="pay" data-v="card" aria-checked="${x.pay === 'card'}" ${dis}>Card ··5521</button><button type="button" role="radio" data-act="pay" data-v="personal" aria-checked="${x.pay === 'personal'}" ${dis}>My money</button></div></div>
      <div class="${ID}-bill"><span class="${ID}-lab">Billable</span><button type="button" role="switch" class="${ID}-switch" data-act="bill" aria-checked="${x.bill}" aria-label="Billable to Halden Energy" ${dis}><i></i></button></div>
    </div>
    <label class="${ID}-f ${ID}-note"><span>Note</span><textarea data-in="note" rows="2" placeholder="Who was there, and why" ${dis}>${esc(x.note)}</textarea></label>`;
}
function render(animate) { renderReport(animate); renderStage(false); renderForm(); }

/* ── actions ── */
function target() { return S.sel.t === 'scan' ? S.scan && S.scan.draft : byK(S.sel.k); }
function select(k, open) {
  S.sel = { t: 'exp', k }; S.scan = null;
  render(false);
  if (open) { S.view = 'detail'; root.dataset.view = 'detail'; }
  const b = $(`[data-lines] [data-k="${k}"]`); if (b && !open) b.focus({ preventScroll: true });
}
function startScan(id) {
  if (locked() || !DOCS[id]) return;
