    S.scan = { phase: 'done', draft: { m: pretty(doc.m), d: doc.d, amt: doc.total, tax: doc.tax, cat: doc.cat, pay: doc.pay.startsWith('VISA') ? 'card' : 'personal', bill: doc.cat !== 'meals', note: '' } };
    renderStage(true); renderForm();
