  S.inbox = S.inbox.filter(x => x !== id);
  let k;
  if (attachTo) { const e = byK(attachTo); e.r = id; k = e.k; }
  else { k = 'e' + (++S.n); S.exp.push({ k, r: id, m: d.m, d: d.d, cat: d.cat, amt: d.amt, tax: d.tax, pay: d.pay, bill: d.bill, note: d.note }); }
  S.sel = { t: 'exp', k }; S.scan = null;
  render(true);
  const row = $(`[data-lines] [data-k="${k}"]`);
  if (row && !RM.matches) row.animate([{ background: 'color-mix(in oklch, var(--apb-receipts-accent) 30%, transparent)' }, { background: 'transparent' }], { duration: 1200, easing: 'ease-out' });
  toast(attachTo ? DOCS[id].img + ' attached to ' + esc(byK(k).m) : esc(d.m) + ' added · ' + usd(d.amt), undo);
}
function removeExp(k) {
  const e = byK(k);
  if (!e || locked()) return;
  snap('Removed ' + e.m);
  if (e.r) S.inbox.push(e.r);
  const list = S.exp.slice().sort((a, b) => a.d - b.d), i = list.indexOf(e);
  S.exp = S.exp.filter(x => x !== e);
  const nxt = list[i + 1] || list[i - 1];
  S.sel = { t: 'exp', k: nxt && nxt !== e ? nxt.k : (S.exp[0] && S.exp[0].k) };
  render(true);
  toast('Removed ' + esc(e.m) + (e.r ? ' · its photo is back in the inbox' : ''), undo);
}
function pulse(el) { if (!el) return; el.classList.remove('is-pulse'); void el.offsetWidth; el.classList.add('is-pulse'); }
function setField(name, value, label, el) {
  const x = target();
  if (!x || locked()) return;
