  if (S.sel.t === 'exp') snap(label);
  x[name] = value;
  if (S.sel.t === 'exp') { renderReport(false); renderForm(); } else renderForm();
}

/* ── submit dialog ── */
const modal = $('[data-modal]'), scrim = $('[data-scrim]');
function openSubmit() {
  const tot = S.exp.reduce((s, e) => s + e.amt, 0), mine = S.exp.filter(e => e.pay === 'personal').reduce((s, e) => s + e.amt, 0);
  modal.innerHTML = `<h3>Submit for approval</h3><p>${S.exp.length} expenses · ${usd(tot)} · you’re owed <b>${usd(mine)}</b></p>
    <ul class="${ID}-route"><li><span>RO</span>Rafael Okafor<small>Project lead</small></li><li><span>FN</span>Finance<small>Usually 2 days</small></li></ul>
    <label class="${ID}-cert"><input type="checkbox" data-cert> I confirm these are genuine business expenses under the Corvid travel policy.</label>
    <div class="${ID}-mrow"><button type="button" class="${ID}-btn" data-act="mclose">Cancel</button><button type="button" class="${ID}-btn is-accent" data-act="confirm" aria-disabled="true" title="Tick the confirmation first">Submit ${usd(tot)}</button></div>`;
