function closeModal() { if (modal.hidden) return; modal.hidden = true; scrim.hidden = true; modal.innerHTML = ''; }

root.addEventListener('click', e => {
  const b = e.target.closest('[data-act], [data-lines] [data-k], [data-field]');
  if (!b || !root.contains(b)) return;
  if (b.dataset.field) { const f = $(`[data-f="${b.dataset.field}"] :is(input, select)`, form); if (f) { f.focus(); if (f.select) f.select(); f.closest(`.${ID}-f`).classList.add('is-hl'); setTimeout(() => f.closest(`.${ID}-f`) && f.closest(`.${ID}-f`).classList.remove('is-hl'), 900); } return; }
  if (!b.dataset.act) { select(b.dataset.k, true); return; }
  if (b.getAttribute('aria-disabled') === 'true') { if (b.dataset.act === 'submit') { const f = $(`[data-lines] .has-flag`); if (f) { select(f.dataset.k, true); toast('Fix this one first: ' + esc(flags(byK(f.dataset.k))[0].t)); } } return; }
  switch (b.dataset.act) {
    case 'scan': startScan(b.dataset.id); break;
    case 'add': addScan(null); break;
    case 'attach': addScan(b.dataset.k); break;
    case 'discard': { const id = S.sel.k; S.sel = { t: 'exp', k: S.exp[0].k }; S.scan = null; render(false); toast(DOCS[id].img + ' stays in your inbox'); break; }
    case 'remove': removeExp(S.sel.k); break;
    case 'cat': setField('cat', b.dataset.v, 'Category → ' + CATS[b.dataset.v], b); break;
    case 'pay': setField('pay', b.dataset.v, b.dataset.v === 'card' ? 'Paid by company card' : 'Paid with my money', b); break;
    case 'bill': setField('bill', !target().bill, 'Billable changed'); break;
    case 'submit': openSubmit(); break;
    case 'mclose': closeModal(); break;
    case 'confirm': {
      closeModal();
      const btn = $('[data-act="submit"]'); if (btn) { btn.classList.add('is-busy'); btn.textContent = 'Submitting…'; }
      setTimeout(() => { if (!root.isConnected) return; snap('Submitted report'); S.status = 'submitted'; render(false); toast('Sent to Rafael Okafor for approval', undo); }, RM.matches ? 60 : 800);
      break;
    }
    case 'recall': snap('Recalled report'); S.status = 'draft'; render(false); toast('Report recalled · you can edit it again', undo); break;
    case 'back': S.view = 'report'; root.dataset.view = 'report'; break;
  }
});
scrim.addEventListener('click', closeModal);
root.addEventListener('change', e => {
  const t = e.target;
  if (t.matches('[data-cert]')) { const c = $('[data-act="confirm"]', modal); if (t.checked) { c.removeAttribute('aria-disabled'); c.removeAttribute('title'); } else { c.setAttribute('aria-disabled', 'true'); c.title = 'Tick the confirmation first'; } return; }
  if (!t.dataset.in) return;
