  if (!x) return;
  let v = t.value;
  if (n === 'amt' || n === 'tax') { v = Math.round(parseFloat(v.replace(/[$,\s]/g, '')) * 100); if (!(v >= 0)) { t.value = (x[n] / 100).toFixed(2); return; } }
  if (n === 'd') v = +v;
  setField(n, v, ({ m: 'Merchant', d: 'Date', amt: 'Amount', tax: 'Tax', note: 'Note' })[n] + ' changed');
});
root.addEventListener('input', e => {
  /* a justification note clears the meal flag as you type */
  if (e.target.dataset.in === 'note' && S.sel.t === 'exp') { const x = byK(S.sel.k); const before = issues(); x.note = e.target.value; if (issues() !== before) { renderReport(false); const fl = $(`.${ID}-flags`, form); const f = flags(x); if (fl) { if (f.length) fl.innerHTML = f.map(y => `<li>${esc(y.t)}</li>`).join(''); else fl.remove(); } } }
});
root.addEventListener('pointerover', e => {
  const f = e.target.closest(`.${ID}-f[data-f], .${ID}-box`);
  $$('.is-link').forEach(x => x.classList.remove('is-link'));
  if (!f) return;
  const k = f.dataset.f || f.dataset.field;
  $$(`.${ID}-box[data-field="${k}"], .${ID}-f[data-f="${k}"]`).forEach(x => x.classList.add('is-link'));
});
root.addEventListener('keydown', e => {
  const t = e.target, k = e.key, typing = t.matches('input:not([type=checkbox]), select, textarea');
  if (!modal.hidden) { if (k === 'Escape') { e.preventDefault(); closeModal(); } return; }
  if ((e.metaKey || e.ctrlKey) && k.toLowerCase() === 'z' && !e.shiftKey && !typing) { e.preventDefault(); undo(); return; }
  if (typing) { if (k === 'Enter' && t.tagName === 'INPUT' && S.sel.t === 'scan') { t.blur(); e.preventDefault(); const p = $(`[data-act="attach"], [data-act="add"]`, form); if (p) p.click(); } return; }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
