  else if (k === 'j' || k === 'k' || ((k === 'ArrowDown' || k === 'ArrowUp') && t.closest('[data-lines]'))) {
    e.preventDefault();
    const rows = $$('[data-lines] [data-k]'), i = rows.findIndex(r => r.dataset.k === S.sel.k), n = rows[Math.max(0, Math.min(rows.length - 1, (i < 0 ? 0 : i) + (k === 'j' || k === 'ArrowDown' ? 1 : -1)))];
    if (n) select(n.dataset.k, false);
  }
  else if ((k === 'Delete' || k === 'Backspace') && S.sel.t === 'exp') { e.preventDefault(); removeExp(S.sel.k); }
  else if (k === 'Enter' && S.sel.t === 'scan' && !t.matches('button')) { e.preventDefault(); const p = $(`[data-act="attach"], [data-act="add"]`, form); if (p) p.click(); }
  else if (k === 'Escape' && S.view === 'detail') { S.view = 'report'; root.dataset.view = 'report'; }
});
render(false);

