.apb-goals {
  --apb-goals-bg: oklch(0.976 0.009 40);
  --apb-goals-ink: oklch(0.26 0.025 35);
  --apb-goals-accent: oklch(0.52 0.13 38);
  --apb-goals-warn: oklch(0.6 0.17 27);
  --apb-goals-card: oklch(1 0 0);
  --apb-goals-sunk: color-mix(in oklch, var(--apb-goals-ink) 4.5%, var(--apb-goals-bg));
  --apb-goals-line: color-mix(in oklch, var(--apb-goals-ink) 11%, transparent);
  --apb-goals-line2: color-mix(in oklch, var(--apb-goals-ink) 20%, transparent);
