@keyframes apb-networth-pulse { 0% { transform: translateX(-50%) scale(1); } 40% { transform: translateX(-50%) scale(1.18); } 100% { transform: translateX(-50%) scale(1); } }
@keyframes apb-networth-in { from { opacity: 0; transform: translateY(6px); } }
@keyframes apb-networth-spin { to { transform: rotate(360deg); } }
@keyframes apb-networth-glint { from { background-position: 150% 0; } to { background-position: -50% 0; } }

.apb-networth {
  --apb-networth-bg: oklch(0.195 0.011 250);
  --apb-networth-ink: oklch(0.95 0.008 240);
  --apb-networth-accent: oklch(0.86 0.085 92);
  --apb-networth-up: oklch(0.78 0.13 155);
  --apb-networth-down: oklch(0.7 0.15 28);
  --apb-networth-deep: color-mix(in oklch, black 28%, var(--apb-networth-bg));
  --apb-networth-raise: color-mix(in oklch, var(--apb-networth-ink) 5%, var(--apb-networth-bg));
  --apb-networth-raise2: color-mix(in oklch, var(--apb-networth-ink) 10%, var(--apb-networth-bg));
  --apb-networth-line: color-mix(in oklch, var(--apb-networth-ink) 10%, transparent);
  --apb-networth-line2: color-mix(in oklch, var(--apb-networth-ink) 18%, transparent);
  --apb-networth-mute: color-mix(in oklch, var(--apb-networth-ink) 58%, var(--apb-networth-bg));
  --apb-networth-faint: color-mix(in oklch, var(--apb-networth-ink) 36%, var(--apb-networth-bg));
  --apb-networth-ease: cubic-bezier(.2, .8, .2, 1);
  --apb-networth-spring: linear(0, .08 4%, .31 9%, .62 15%, .87 21%, 1.02 27%, 1.07 33%, 1.05 39%, 1.01 48%, .995 60%, 1);
  --apb-networth-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; box-sizing: border-box; width: 100%; height: var(--apb-networth-h, 680px);
  container-type: inline-size; container-name: apb-networth;
  overflow: clip; isolation: isolate; border-radius: 16px; border: 1px solid var(--apb-networth-line);
  background: radial-gradient(70% 55% at 18% 0%, color-mix(in oklch, var(--apb-networth-accent) 7%, transparent), transparent 70%), radial-gradient(60% 50% at 100% 100%, color-mix(in oklch, oklch(0.6 0.08 200) 8%, transparent), transparent 70%), var(--apb-networth-bg);
  color: var(--apb-networth-ink);
  font: 13.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--apb-networth-accent);
  -webkit-font-smoothing: antialiased;

