  &:focus { outline: none; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & svg { display: block; width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apb-networth-accent); outline-offset: 2px; border-radius: 7px; }
  & kbd { font: 600 10px/1 var(--apb-networth-mono); padding: 2px 4px; border-radius: 4px; background: var(--apb-networth-raise2); color: var(--apb-networth-faint); }
  & .is-up { color: var(--apb-networth-up); } & .is-down { color: var(--apb-networth-down); }

  & .apb-networth-app { display: grid; height: 100%; grid-template-columns: minmax(0, 1fr) 372px; }

