  & .apb-networth-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "brand brand" "fig ctl"; align-items: end; gap: 8px 16px; padding: 16px 20px 6px; }
  & .apb-networth-brand { grid-area: brand; display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--apb-networth-mute);
