    & b { display: block; font-size: clamp(34px, 4.6cqi, 54px); font-weight: 280; letter-spacing: -.045em; line-height: 1.02; font-variant-numeric: tabular-nums; background: linear-gradient(100deg, var(--apb-networth-ink) 40%, color-mix(in oklch, var(--apb-networth-accent) 70%, white) 50%, var(--apb-networth-ink) 60%) 0 0 / 250% 100%; -webkit-background-clip: text; background-clip: text; color: transparent; animation: apb-networth-glint 3.2s var(--apb-networth-ease) .4s both; }
