  }
  & .apb-networth-home { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--apb-networth-mute); white-space: nowrap; }
  & .apb-networth-switch { position: relative; width: 36px; height: 21px; border-radius: 99px; background: var(--apb-networth-line2); transition: background-color .25s;
    & i { position: absolute; top: 3px; left: 3px; width: 15px; height: 15px; border-radius: 50%; background: var(--apb-networth-ink); transition: transform .4s var(--apb-networth-spring), background-color .2s; }
    &[aria-checked="true"] { background: var(--apb-networth-accent); & i { transform: translateX(15px); background: var(--apb-networth-bg); } }
  }
  & .apb-networth-ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--apb-networth-mute); transition: background-color .15s, color .15s;
    &:hover:not(:disabled) { background: var(--apb-networth-raise2); color: var(--apb-networth-ink); }
  }
