    & canvas { position: absolute; inset: 0; display: block; }
  }
  & .apb-networth-handle { position: absolute; left: 0; top: 0; bottom: 28px; width: 0; pointer-events: none; transition: transform .12s linear;
    & span.is-pulse { animation: apb-networth-pulse .45s var(--apb-networth-spring); }
    & span { position: absolute; left: 0; top: -2px; transform: translateX(-50%); padding: 3px 8px; border-radius: 99px; font: 700 10.5px/1.2 system-ui; white-space: nowrap; background: var(--apb-networth-accent); color: var(--apb-networth-bg); box-shadow: 0 6px 14px -6px black; }
  }
