    &.is-in { transform: translate(-50%, 0); opacity: 1; }
    & span { padding: 3px 0; }
    & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 9px; border-radius: 7px; font-weight: 700; color: oklch(0.5 0.12 75); white-space: nowrap; }
    & kbd { background: transparent; color: inherit; border: 1px solid currentColor; opacity: .7; }
  }

  /* ── responsive ── */
  @container apb-networth (max-width: 1000px) {
    & .apb-networth-app { grid-template-columns: minmax(0, 1fr) 320px; }
    & .apb-networth-head { grid-template-areas: "brand brand" "fig fig" "ctl ctl"; }
    & .apb-networth-ctl { justify-content: flex-start; }
    & .apb-networth-spark { display: none; }
    & .apb-networth-acct { grid-template-columns: 4px minmax(0, 1fr) auto; }
  }
  @container apb-networth (max-width: 759px) {
    & .apb-networth-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: max-content max-content; overflow: auto; overscroll-behavior: contain; }
    & .apb-networth-main { grid-template-rows: auto 260px auto; }
    & .apb-networth-sheet { grid-template-rows: auto auto auto; border-left: 0; border-top: 1px solid var(--apb-networth-line); min-height: auto; }
    & .apb-networth-sscroll { overflow: visible; }
    & .apb-networth-drawer { width: 100%; }
    & .apb-networth-head { padding: 14px 14px 4px; }
    & .apb-networth-foot { padding: 8px 14px 12px; }
  }
  @container apb-networth (max-width: 420px) {
    & .apb-networth-range kbd, & .apb-networth-home kbd { display: none; }
    & .apb-networth-dstats { grid-template-columns: 1fr 1fr; }
  }

  @media (prefers-reduced-motion: reduce) {
    & *, & *::before, & *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; animation-delay: 0s !important; }
    & .apb-networth-fig b { animation: none; background: none; color: var(--apb-networth-ink); }
  }
}

