const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
/* FLIP: measure keyed children, mutate, then play every move from where it was */
function flip(list, mutate, o) {
  const first = new Map(list().map(e => [e.dataset.k, e.getBoundingClientRect()]));
  mutate();
  if (RM.matches) return;
  list().forEach((e, i) => {
    const f = first.get(e.dataset.k), l = e.getBoundingClientRect();
    if (!f) { e.animate([{ opacity: 0, transform: 'translateY(6px) scale(.98)' }, { opacity: 1, transform: 'none' }], { duration: 320, delay: (o && o.stagger || 0) * i, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' }); return; }
    const dx = f.left - l.left, dy = f.top - l.top;
    if (Math.abs(dx) + Math.abs(dy) > .5) e.animate([{ transform: `translate(${dx}px,${dy}px)` }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.2,.9,.25,1)' });
  });
}
/* one toast at a time, inside the root, with an optional Undo */
let toastT = 0;
function toast(msg, undo) {
  const t = $('[data-toast]');
  if (!t) return;
  clearTimeout(toastT);
  t.innerHTML = '<span>' + msg + '</span>' + (undo ? '<button type="button" data-toast-undo>Undo <kbd>' + MOD + ' Z</kbd></button>' : '');
  t.hidden = false; t.classList.remove('is-in'); void t.offsetWidth; t.classList.add('is-in');
  const b = t.querySelector('[data-toast-undo]');
  if (b) b.onclick = () => { undo(); hideToast(); };
  toastT = setTimeout(hideToast, undo ? 6000 : 3200);
}
function hideToast() { const t = $('[data-toast]'); if (t) { t.classList.remove('is-in'); t.hidden = true; } }

/* ── Tidemark · net worth over two years. One table of monthly balances feeds the stacked chart, the
      balance sheet, the milestones and the headline; scrubbing rewinds all of them together ── */
const ID = 'apb-networth';
const N = 24, MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const mlabel = (i, long) => { const t = 10 + i; return (long ? ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'] : MON)[t % 12] + ' ' + (2024 + Math.floor(t / 12)); };
const usd = v => (v < 0 ? '−' : '') + '$' + Math.abs(Math.round(v)).toLocaleString('en-US');
const sgn = v => (v > 0 ? '+' : v < 0 ? '−' : '±') + '$' + Math.abs(Math.round(v)).toLocaleString('en-US');
const kfmt = v => (v < 0 ? '−' : '') + '$' + (Math.abs(v) >= 1000 ? Math.round(Math.abs(v) / 1000) + 'k' : Math.abs(v));
const GROUPS = [
  { k: 'prop', n: 'Property', side: 'a', c: 'oklch(0.62 0.045 70)' },
  { k: 'inv', n: 'Investments', side: 'a', c: 'oklch(0.78 0.12 84)' },
  { k: 'cash', n: 'Cash', side: 'a', c: 'oklch(0.74 0.09 190)' },
  { k: 'mort', n: 'Mortgage', side: 'l', c: 'oklch(0.58 0.12 18)' },
  { k: 'debt', n: 'Other debt', side: 'l', c: 'oklch(0.7 0.13 42)' }
];
const G = Object.fromEntries(GROUPS.map(g => [g.k, g]));
const ACCTS = [
  { k: 'chk', n: 'Checking', inst: 'Harbor & Pine ··2210', g: 'cash', f: i => 3200 + 900 * Math.sin(i * 1.3) + 40 * i },
  { k: 'sav', n: 'High-yield savings', inst: 'Lumen Bank ··8841', g: 'cash', f: i => 8000 + 420 * i - (i >= 14 ? 2000 : 0) },
  { k: 'brk', n: 'Brokerage', inst: 'Index funds · Calder Invest', g: 'inv', f: i => 21000 * (1 + .009 * i + .035 * Math.sin(i * .8)) + 500 * i },
  { k: 'ret', n: '401(k)', inst: 'Quillfeather Labs plan', g: 'inv', f: i => 46000 + 1150 * i + 2000 * Math.sin(i * .6) },
  { k: 'home', n: 'Home', inst: '14 Alder Court · your estimate', g: 'prop', manual: true, f: i => 412000 + 3300 * Math.floor(i / 3) },
  { k: 'car', n: 'Car', inst: '2021 hatchback · your estimate', g: 'prop', manual: true, f: i => 19500 - 280 * i },
  { k: 'mtg', n: 'Mortgage', inst: 'Fenmore Lending · 5.1%', g: 'mort', f: i => 318000 - 640 * i },
  { k: 'auto', n: 'Car loan', inst: 'Lakeline Credit Union', g: 'debt', f: i => Math.max(0, 14200 - 410 * i) },
  { k: 'card', n: 'Credit card', inst: 'Juniper Card ··3307', g: 'debt', f: i => 1800 + 700 * Math.abs(Math.sin(i * 1.1)) },
  { k: 'stu', n: 'Student loan', inst: 'Fairpath Servicing', g: 'debt', f: i => 22400 - 260 * i }
];
const A = Object.fromEntries(ACCTS.map(a => [a.k, a]));
const side = k => G[A[k].g].side;
const S = {
  i: N - 1, range: 24, off: new Set(), open: null,
  V: Object.fromEntries(ACCTS.map(a => [a.k, Array.from({ length: N }, (_, i) => Math.round(a.f(i)))]))
};
const val = (k, i) => S.V[k][i];
const on = k => !S.off.has(k);
const total = (s, i) => ACCTS.filter(a => side(a.k) === s && on(a.k)).reduce((t, a) => t + val(a.k, i), 0);
const net = i => total('a', i) - total('l', i);
const groupVal = (g, i) => ACCTS.filter(a => a.g === g && on(a.k)).reduce((t, a) => t + val(a.k, i), 0);
function milestones() {
  const out = [];
  for (let th = 50000; th <= 1000000; th += 50000) {
    const first = Array.from({ length: N }, (_, i) => i).find(i => i > 0 && net(i) >= th && net(i - 1) < th);
    if (first !== undefined) out.push({ th, i: first });
  }
  return out;
}

/* ── history ── */
const hist = [];
const snap = label => hist.push({ label, d: JSON.stringify({ V: S.V, off: [...S.off] }) });
function undo() {
  const h = hist.pop();
  if (!h) return;
  const d = JSON.parse(h.d); S.V = d.V; S.off = new Set(d.off);
  render(true);
  toast('Undid: ' + esc(h.label));
}

/* ── chart ── */
const cwrap = $('[data-cwrap]'), cv = $('[data-canvas]'), ctx = cv.getContext('2d'), handle = $('[data-handle]');
let W = 0, H = 0, dpr = 1, frame = null, raf = 0, visible = true, dom = N - S.range;
const PAD = { l: 52, r: 16, t: 18, b: 28 };
function target() {
  const f = { net: [], g: {} };
  GROUPS.forEach(g => { f.g[g.k] = Array.from({ length: N }, (_, i) => groupVal(g.k, i)); });
  f.net = Array.from({ length: N }, (_, i) => net(i));
  return f;
}
function size() {
  const r = cwrap.getBoundingClientRect();
  dpr = Math.min(2, window.devicePixelRatio || 1); W = Math.max(240, r.width); H = Math.max(160, r.height);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr); cv.style.width = W + 'px'; cv.style.height = H + 'px';
}
function tweenTo(fromZero) {
  const to = target(), toDom = N - S.range;
  if (RM.matches || !visible || !frame) { frame = to; dom = toDom; draw(); return; }
  const f0 = fromZero ? { net: to.net.map(() => 0), g: Object.fromEntries(GROUPS.map(g => [g.k, to.g[g.k].map(() => 0)])) } : frame, d0 = dom, t0 = performance.now(), D = fromZero ? 900 : 600;
  cancelAnimationFrame(raf);
  const step = now => {
    if (!root.isConnected) return;
    const p = Math.min(1, (now - t0) / D), e = p === 1 ? 1 : 1 - Math.pow(2, -10 * p);
    const lerp = (a, b) => a.map((v, i) => v + (b[i] - v) * e);
    frame = { net: lerp(f0.net, to.net), g: Object.fromEntries(GROUPS.map(g => [g.k, lerp(f0.g[g.k], to.g[g.k])])) };
    dom = d0 + (toDom - d0) * e;
    draw();
    if (p < 1 && visible) raf = requestAnimationFrame(step); else { frame = to; dom = toDom; draw(); }
  };
  raf = requestAnimationFrame(step);
}
function nice(span) { const p = Math.pow(10, Math.floor(Math.log10(span))), m = span / p; return (m < 1.5 ? 1 : m < 3.5 ? 2.5 : m < 7.5 ? 5 : 10) * p; }
function geo() {
  const lo = Math.max(0, Math.floor(dom)), hi = N - 1;
  let top = 1, bot = 0;
  for (let i = lo; i <= hi; i++) {
    top = Math.max(top, GROUPS.filter(g => g.side === 'a').reduce((s, g) => s + frame.g[g.k][i], 0), frame.net[i]);
    bot = Math.max(bot, GROUPS.filter(g => g.side === 'l').reduce((s, g) => s + frame.g[g.k][i], 0));
  }
  const step = nice((top + bot) / 4), yMax = Math.ceil(top / step) * step, yMin = -Math.ceil(bot / step) * step;
  const pw = W - PAD.l - PAD.r, ph = H - PAD.t - PAD.b, span = Math.max(1, N - 1 - dom);
  return { yMax, yMin, step, X: i => PAD.l + (i - dom) / span * pw, Y: v => PAD.t + (yMax - v) / (yMax - yMin || 1) * ph, pw, ph, lo };
}
function draw() {
  if (!frame || !W) return;
  const cs = getComputedStyle(root), ink = cs.color, gold = cs.getPropertyValue('--apb-networth-accent').trim() || 'gold';
  const g = geo(), { X, Y } = g;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  ctx.save(); ctx.beginPath(); ctx.rect(PAD.l, 0, W - PAD.l, H); ctx.clip();
  ctx.font = '500 10.5px ui-monospace, Menlo, monospace';
  /* grid */
  for (let v = g.yMin; v <= g.yMax + 1; v += g.step) { ctx.strokeStyle = ink; ctx.globalAlpha = v === 0 ? .35 : .08; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(PAD.l, Y(v)); ctx.lineTo(W - PAD.r, Y(v)); ctx.stroke(); }
  ctx.globalAlpha = 1;
  /* stacked areas: assets up from zero, liabilities down */
  ['a', 'l'].forEach(sd => {
    let base = new Array(N).fill(0);
    GROUPS.filter(x => x.side === sd).forEach(gr => {
      const vals = frame.g[gr.k], next = base.map((b, i) => b + vals[i]);
      const s = sd === 'a' ? 1 : -1;
      ctx.beginPath();
      for (let i = g.lo; i < N; i++) { const x = X(i), y = Y(s * next[i]); i === g.lo ? ctx.moveTo(x, y) : ctx.lineTo(x, y); }
      for (let i = N - 1; i >= g.lo; i--) ctx.lineTo(X(i), Y(s * base[i]));
      ctx.closePath();
      ctx.fillStyle = gr.c; ctx.globalAlpha = sd === 'a' ? .5 : .42; ctx.fill();
      ctx.globalAlpha = .9; ctx.strokeStyle = gr.c; ctx.lineWidth = 1; ctx.beginPath();
      for (let i = g.lo; i < N; i++) { const x = X(i), y = Y(s * next[i]); i === g.lo ? ctx.moveTo(x, y) : ctx.lineTo(x, y); }
      ctx.stroke(); ctx.globalAlpha = 1;
      base = next;
    });
  });
  /* net worth */
  ctx.beginPath();
  for (let i = g.lo; i < N; i++) { const x = X(i), y = Y(frame.net[i]); i === g.lo ? ctx.moveTo(x, y) : ctx.lineTo(x, y); }
  ctx.strokeStyle = ink; ctx.lineWidth = 2.5; ctx.lineJoin = 'round'; ctx.shadowColor = 'rgba(0,0,0,.6)'; ctx.shadowBlur = 8; ctx.stroke(); ctx.shadowBlur = 0;
  milestones().forEach(m => { if (m.i < g.lo) return; const x = X(m.i), y = Y(frame.net[m.i]); ctx.fillStyle = gold; ctx.beginPath(); ctx.moveTo(x, y - 6); ctx.lineTo(x, y - 22); ctx.lineTo(x + 11, y - 18); ctx.lineTo(x, y - 14); ctx.fill(); ctx.strokeStyle = gold; ctx.lineWidth = 1.25; ctx.beginPath(); ctx.moveTo(x, y - 4); ctx.lineTo(x, y - 22); ctx.stroke(); });
  /* scrub */
  const sx = X(S.i);
  ctx.strokeStyle = gold; ctx.globalAlpha = .9; ctx.lineWidth = 1; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(sx, PAD.t); ctx.lineTo(sx, H - PAD.b); ctx.stroke(); ctx.setLineDash([]); ctx.globalAlpha = 1;
  ctx.fillStyle = gold; ctx.beginPath(); ctx.arc(sx, Y(frame.net[S.i]), 5.5, 0, 7); ctx.fill(); ctx.strokeStyle = cs.backgroundColor; ctx.lineWidth = 2; ctx.stroke();
  ctx.restore();
  /* axes labels */
  ctx.fillStyle = ink; ctx.globalAlpha = .5; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
  for (let v = g.yMin; v <= g.yMax + 1; v += g.step) ctx.fillText(kfmt(v), PAD.l - 8, Y(v));
  ctx.textAlign = 'center'; ctx.textBaseline = 'top';
  const every = S.range <= 6 ? 1 : S.range <= 12 ? 2 : 3;
  for (let i = Math.ceil(g.lo); i < N; i++) if ((N - 1 - i) % every === 0) { const x = X(i); if (x >= PAD.l + 10) ctx.fillText(MON[(10 + i) % 12] + ((10 + i) % 12 === 0 ? ' ’' + String(24 + Math.floor((10 + i) / 12)) : ''), Math.min(x, W - PAD.r - 14), H - PAD.b + 9); }
  ctx.globalAlpha = 1;
  handle.style.transform = `translateX(${sx.toFixed(1)}px)`;
}

/* ── headline ── */
let shownNW = null, nwRaf = 0;
function headline() {
  const v = net(S.i), lo = N - S.range, d = v - net(lo), pct = net(lo) ? d / Math.abs(net(lo)) * 100 : 0;
  $('[data-asof]').textContent = (S.off.has('home') ? 'Net worth without home · ' : 'Net worth · ') + mlabel(S.i, true);
  $('[data-chg]').innerHTML = `<span class="${d >= 0 ? 'is-up' : 'is-down'}">${sgn(d)} · ${d >= 0 ? '+' : '−'}${Math.abs(pct).toFixed(1)}%</span> since ${mlabel(lo)}${S.i < N - 1 ? ` · <button type="button" data-act="latest">Back to today</button>` : ''}`;
  cwrap.setAttribute('aria-valuenow', S.i); cwrap.setAttribute('aria-valuetext', mlabel(S.i, true) + ', ' + usd(v));
  $('[data-hlabel]').textContent = mlabel(S.i);
  const el = $('[data-nw]'), from = shownNW ?? v;
  shownNW = v;
  cancelAnimationFrame(nwRaf);
  if (RM.matches || from === v) { el.textContent = usd(v); return; }
  const t0 = performance.now();
  const step = now => {
    if (!root.isConnected) return;
    const p = Math.min(1, (now - t0) / 420), e = 1 - Math.pow(1 - p, 3);
    el.textContent = usd(from + (v - from) * e);
    if (p < 1) nwRaf = requestAnimationFrame(step);
  };
  nwRaf = requestAnimationFrame(step);
}

/* ── balance sheet ── */
const sheet = $('[data-sheet]');
function spark(k, w, h, mark) {
  const lo = N - S.range, vs = S.V[k].slice(lo), mn = Math.min(...vs), mx = Math.max(...vs), r = mx - mn || 1;
  const pts = vs.map((v, i) => `${(i / (vs.length - 1) * w).toFixed(1)},${(h - 2 - (v - mn) / r * (h - 4)).toFixed(1)}`).join(' ');
  const mi = S.i - lo;
  return `<svg class="${ID}-spark" viewBox="0 0 ${w} ${h}" style="width:${w}px;height:${h}px" aria-hidden="true"><polyline points="${pts}"/>${mark && mi >= 0 ? `<circle cx="${(mi / (vs.length - 1) * w).toFixed(1)}" cy="${(h - 2 - (vs[mi] - mn) / r * (h - 4)).toFixed(1)}" r="3"/>` : ''}</svg>`;
}
function renderSheet() {
  const i = S.i, prev = Math.max(0, i - 1);
  const row = a => {
    const v = val(a.k, i), d = v - val(a.k, prev), good = side(a.k) === 'a' ? d >= 0 : d <= 0;
    return `<div class="${ID}-row${on(a.k) ? '' : ' is-off'}" style="--c:${G[a.g].c}">
      <input type="checkbox" data-inc="${a.k}" ${on(a.k) ? 'checked' : ''} aria-label="Count ${esc(a.n)} in net worth" title="${on(a.k) ? 'Counted' : 'Not counted'} in net worth">
      <button type="button" class="${ID}-acct" data-act="open" data-k="${a.k}" aria-label="${esc(a.n)}, ${usd(v)}. Open details"><i></i><span class="${ID}-an"><b>${esc(a.n)}</b><small>${esc(a.inst)}</small></span>${spark(a.k, 54, 20)}<span class="${ID}-av"><b>${usd(v)}</b><small class="${d === 0 ? '' : good ? 'is-up' : 'is-down'}">${i === 0 ? 'first month' : sgn(d)}</small></span></button></div>`;
  };
  const ta = total('a', i), tl = total('l', i);
  sheet.innerHTML = `<header class="${ID}-shead"><h3>Balance sheet</h3><span>${mlabel(i, true)}</span></header>
    <div class="${ID}-sscroll">
    <section><h4><span>Assets</span><b>${usd(ta)}</b></h4>${ACCTS.filter(a => side(a.k) === 'a').map(row).join('')}</section>
    <section><h4><span>Liabilities</span><b>${usd(-tl)}</b></h4>${ACCTS.filter(a => side(a.k) === 'l').map(row).join('')}</section>
    </div>
    <footer class="${ID}-sfoot"><span>${usd(ta)} − ${usd(tl)}</span><b>${usd(ta - tl)}</b></footer>`;
}
function renderMiles() {
  const ms = milestones();
  $('[data-miles]').innerHTML = ms.map(m => `<li><button type="button" data-act="mile" data-i="${m.i}" aria-pressed="${S.i === m.i}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 21V4M6 4.5h11l-2.5 3.5L17 11.5H6"/></svg>Crossed ${kfmt(m.th)}<small>${mlabel(m.i)}</small></button></li>`).join('') || `<li class="${ID}-nomile">No new $50k milestone in this view.</li>`;
  $('[data-legend]').innerHTML = GROUPS.map(g => `<span style="--c:${g.c}" class="${GROUPS.some(x => x.k === g.k && ACCTS.filter(a => a.g === g.k).every(a => !on(a.k))) ? 'is-off' : ''}">${g.n}</span>`).join('') + '<span class="is-net">Net worth</span>';
}
function renderDrawer() {
  const dr = $('[data-drawer]'), a = A[S.open];
  if (!a) { dr.hidden = true; dr.innerHTML = ''; return; }
  const i = S.i, v = val(a.k, i), y1 = v - val(a.k, Math.max(0, i - 12)), first = val(a.k, 0);
  dr.hidden = false;
  dr.innerHTML = `<header><span class="${ID}-dot" style="--c:${G[a.g].c}"></span><div><h3>${esc(a.n)}</h3><small>${esc(a.inst)}</small></div><button type="button" class="${ID}-ib" data-act="close" aria-label="Close">${'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>'}</button></header>
    <div class="${ID}-dbig"><small>${mlabel(i, true)}</small><b>${usd(v)}</b></div>
    <div class="${ID}-dspark">${spark(a.k, 300, 84, true)}</div>
    <dl class="${ID}-dstats"><div><dt>12 months</dt><dd class="${(side(a.k) === 'a') === (y1 >= 0) ? 'is-up' : 'is-down'}">${sgn(y1)}</dd></div><div><dt>Since ${mlabel(0)}</dt><dd>${sgn(v - first)}</dd></div><div><dt>Share of ${side(a.k) === 'a' ? 'assets' : 'debts'}</dt><dd>${(v / Math.max(1, total(side(a.k), i)) * 100).toFixed(1)}%</dd></div></dl>
    ${a.manual ? `<form class="${ID}-upd" data-upd novalidate><label><span>Your estimate for October 2026</span><span class="${ID}-money"><small>$</small><input data-uval inputmode="numeric" value="${val(a.k, N - 1)}"></span></label><p class="${ID}-err" data-uerr role="alert"></p><button type="submit" class="${ID}-btn is-accent">Update value</button></form>`
      : `<div class="${ID}-sync"><p>Linked · synced today, 9:14 AM</p><button type="button" class="${ID}-btn" data-act="sync">Sync now</button></div>`}`;
}
function render(animate) {
  if (S.i < N - S.range) S.i = N - S.range;
  headline(); renderSheet(); renderMiles(); renderDrawer();
